function formatNumber(value) {
    return Math.floor(value).toLocaleString();
}

function formatUiNumber(value) {
    const number = Math.floor(Number(value) || 0);

    if (number >= 1000000) {
        return `${(number / 1000000).toFixed(number >= 10000000 ? 0 : 1)}M`;
    }

    if (number >= 10000) {
        return `${(number / 1000).toFixed(number >= 100000 ? 0 : 1)}K`;
    }

    return number.toLocaleString();
}


function formatDockCost(value) {
    const number = Math.floor(Number(value) || 0);

    if (number >= 1000000) {
        return `${(number / 1000000).toFixed(1)}M`;
    }

    if (number >= 1000) {
        return `${(number / 1000).toFixed(number >= 10000 ? 0 : 1)}K`;
    }

    return number.toLocaleString();
}

function clamp(value, min, max) {
    return Math.min(max, Math.max(min, value));
}

function getDictionaryWordCount() {
    let total = 0;
    wordsByLength.forEach((wordSet) => {
        total += wordSet.size;
    });
    return total;
}

function getDisplayWord(word, maxLength = 10) {
    const cleanWord = String(word);
    if (cleanWord.length <= maxLength) {
        return cleanWord;
    }
    return `${cleanWord.slice(0, maxLength - 1)}…`;
}

function getMonkeyType(typeId) {
    return MONKEY_TYPES.find((type) => type.id === typeId) || MONKEY_TYPES[0];
}

function getRandomFromList(items) {
    if (!Array.isArray(items) || items.length === 0) {
        return undefined;
    }

    return items[Math.floor(Math.random() * items.length)];
}

function getCurrentOffice() {
    return OFFICE_BUILDINGS[clamp(officeLevel, 1, OFFICE_BUILDINGS.length) - 1];
}

function getNextOffice() {
    return OFFICE_BUILDINGS[officeLevel] || null;
}

function getUpgradeLevel(upgradeId) {
    return Number(upgrades[upgradeId]) || 0;
}

function getUpgradeCost(upgradeId) {
    const upgrade = UPGRADE_DEFS[upgradeId];
    const level = getUpgradeLevel(upgradeId);
    return Math.floor(upgrade.baseCost * Math.pow(upgrade.costMultiplier, level));
}

function getOwnedMonkeyTypeIds() {
    return new Set(monkeyRoster);
}

function getMonkeyTypeCounts() {
    return monkeyRoster.reduce((counts, typeId) => {
        counts[typeId] = (counts[typeId] || 0) + 1;
        return counts;
    }, {});
}

function getOwnedMonkeyTypeBreakdown(ownedTypeIds = getOwnedMonkeyTypeIds()) {
    const normalOwned = normalMonkeyTypeIds.filter((typeId) => ownedTypeIds.has(typeId)).length;
    const rareOwned = rareMonkeyTypeIds.filter((typeId) => ownedTypeIds.has(typeId)).length;
    const superRareOwned = superRareMonkeyTypeIds.filter((typeId) => ownedTypeIds.has(typeId)).length;
    const legendaryOwned = legendaryMonkeyTypeIds.filter((typeId) => ownedTypeIds.has(typeId)).length;

    return {
        totalOwned: normalOwned + rareOwned + superRareOwned + legendaryOwned,
        normalOwned,
        rareOwned,
        superRareOwned,
        legendaryOwned
    };
}

function emptyCollectionBonuses() {
    return {
        speedBonus: 0,
        incomeBonus: 0,
        rareBonus: 0,
        flatWordBonus: 0
    };
}

function addCollectionBonus(total, bonus = {}) {
    total.speedBonus += Number(bonus.speedBonus) || 0;
    total.incomeBonus += Number(bonus.incomeBonus) || 0;
    total.rareBonus += Number(bonus.rareBonus) || 0;
    total.flatWordBonus += Number(bonus.flatWordBonus) || 0;
    return total;
}

function getCollectionBonusProgress(definition, breakdown = getOwnedMonkeyTypeBreakdown()) {
    switch (definition.group) {
        case 'normal':
            return breakdown.normalOwned;
        case 'rare':
            return breakdown.rareOwned;
        case 'super-rare':
            return breakdown.superRareOwned;
        case 'legendary':
            return breakdown.legendaryOwned;
        default:
            return breakdown.totalOwned;
    }
}

function getPassiveCollectionBonuses() {
    const ownedTypeIds = getOwnedMonkeyTypeIds();
    const breakdown = getOwnedMonkeyTypeBreakdown(ownedTypeIds);
    const bonuses = emptyCollectionBonuses();

    COLLECTION_BONUS_DEFS.forEach((definition) => {
        if (getCollectionBonusProgress(definition, breakdown) >= definition.target) {
            addCollectionBonus(bonuses, definition.bonus);
        }
    });

    return bonuses;
}

function getClaimedCollectionRewardBonuses() {
    const bonuses = emptyCollectionBonuses();

    COLLECTION_REWARDS.forEach((reward) => {
        if (claimedCollectionRewards.includes(reward.id)) {
            addCollectionBonus(bonuses, reward.bonus);
        }
    });

    return bonuses;
}

function getClaimedOfficeRewardBonuses() {
    const bonuses = emptyCollectionBonuses();

    OFFICE_BUILDINGS.forEach((office) => {
        if (claimedOfficeRewards.includes(office.id)) {
            addCollectionBonus(bonuses, office.completionReward);
        }
    });

    return bonuses;
}

function getCollectionBonuses() {
    const bonuses = getPassiveCollectionBonuses();
    return addCollectionBonus(bonuses, getClaimedCollectionRewardBonuses());
}

function getCollectionRewardBonusText(bonus = {}) {
    const parts = [];

    if (bonus.speedBonus) {
        parts.push(`+${Math.round(bonus.speedBonus * 100)}% typing speed`);
    }

    if (bonus.incomeBonus) {
        parts.push(`+${Math.round(bonus.incomeBonus * 100)}% word income`);
    }

    if (bonus.rareBonus) {
        parts.push(`+${Math.round(bonus.rareBonus * 100)}% super rare odds`);
    }

    if (bonus.flatWordBonus) {
        parts.push(`+${bonus.flatWordBonus} banana${bonus.flatWordBonus === 1 ? '' : 's'} per word`);
    }

    return parts.join(' • ');
}

function getCollectionRewardText(reward) {
    const parts = [];

    if (reward.rewardBananas > 0) {
        parts.push(`${formatNumber(reward.rewardBananas)} bananas`);
    }

    const bonusText = getCollectionRewardBonusText(reward.bonus);
    if (bonusText) {
        parts.push(bonusText);
    }

    return parts.length > 0 ? parts.join(' • ') : 'Permanent bonus';
}

function getUniqueMonkeyTypeCount() {
    return getOwnedMonkeyTypeBreakdown().totalOwned;
}

function getCollectionRewardTotalCount() {
    ensureMonkeyRosterMatchesCount();
    return Math.max(monkeysOwned, lifetimeStats.monkeysHired || 0, monkeyRoster.length || 0);
}

function getCollectionRewardBasis(reward) {
    return reward && reward.id === 'collected-all'
        ? getUniqueMonkeyTypeCount()
        : getCollectionRewardTotalCount();
}

function getCollectionRewardProgress(reward) {
    return Math.min(getCollectionRewardBasis(reward), reward.target);
}

function canClaimCollectionReward(reward) {
    return Boolean(reward) && !claimedCollectionRewards.includes(reward.id) && getCollectionRewardBasis(reward) >= reward.target;
}

function getClaimableCollectionRewardCount() {
    return COLLECTION_REWARDS.filter(canClaimCollectionReward).length;
}

function getRareChance() {
    return RARITY_CONFIG.rare.baseChance;
}

function getLegendaryChance() {
    return RARITY_CONFIG.legendary.baseChance;
}

function getSuperRareChance() {
    const office = getCurrentOffice();
    const recruiterBonus = getUpgradeLevel('rareRecruiter') * 0.01;
    const collectionBonus = getCollectionBonuses().rareBonus;
    const officeCompletionBonus = getClaimedOfficeRewardBonuses().rareBonus;
    return clamp(baseSuperRareChance + recruiterBonus + office.rareBonus + collectionBonus + officeCompletionBonus, RARITY_CONFIG['super-rare'].baseChance, 0.35);
}

function getNormalChance() {
    return Math.max(0, 1 - getLegendaryChance() - getSuperRareChance() - getRareChance());
}

function getGlobalSpeedMultiplier() {
    const office = getCurrentOffice();
    const upgradeBonus = getUpgradeLevel('fasterTypewriters') * 0.08;
    const collectionBonus = getCollectionBonuses().speedBonus;
    const officeCompletionBonus = getClaimedOfficeRewardBonuses().speedBonus;
    return 1 + office.speedBonus + upgradeBonus + collectionBonus + officeCompletionBonus;
}

function normalizeDiscoveredWords(rawWords = discoveredWords) {
    if (!Array.isArray(rawWords)) {
        return [];
    }

    const validWords = new Set();
    wordsByLength.forEach((wordSet) => {
        wordSet.forEach((word) => validWords.add(word));
    });

    return [...new Set(
        rawWords
            .map((word) => String(word || '').toLowerCase().trim())
            .filter((word) => word.length >= minWordLength && validWords.has(word))
    )];
}

function hasDiscoveredWord(word) {
    return discoveredWords.includes(String(word).toLowerCase());
}

function getDiscoveredWordCount() {
    return discoveredWords.length;
}

function markDiscoveredWord(word) {
    const normalizedWord = String(word).toLowerCase();
    if (!hasDiscoveredWord(normalizedWord)) {
        discoveredWords.push(normalizedWord);
        discoveredWords = normalizeDiscoveredWords(discoveredWords);
        lifetimeStats.uniqueWords = getDiscoveredWordCount();
        return true;
    }

    return false;
}

function getLengthBonusMultiplier(word) {
    const length = String(word).length;

    if (length >= 7) {
        return 3;
    }

    if (length >= 6) {
        return 2.5;
    }

    if (length >= 5) {
        return 1.75;
    }

    if (length >= 4) {
        return 1.25;
    }

    return 1;
}

function getLengthBonusLabel(word) {
    const length = String(word).length;

    if (length >= 7) {
        return 'JACKPOT';
    }

    if (length >= 6) {
        return 'BIG WORD';
    }

    if (length >= 5) {
        return 'LONG';
    }

    if (length >= 4) {
        return 'BONUS';
    }

    return '';
}

function getFirstDiscoveryBonus(word) {
    return Math.max(10, String(word).length * 3);
}

function getWordIncomeMultiplier() {
    const office = getCurrentOffice();
    const payrollBonus = getUpgradeLevel('bananaPayroll') * 0.12;
    const collectionBonus = getCollectionBonuses().incomeBonus;
    const officeCompletionBonus = getClaimedOfficeRewardBonuses().incomeBonus;
    return office.incomeMultiplier * (1 + payrollBonus + collectionBonus + officeCompletionBonus);
}

function getFlatWordBonus() {
    const office = getCurrentOffice();
    return office.wordBonus + getUpgradeLevel('betterDictionary') + getCollectionBonuses().flatWordBonus + getClaimedOfficeRewardBonuses().flatWordBonus;
}

function calculateWordPoints(word, options = {}) {
    const normalizedWord = String(word).toLowerCase();
    const basePoints = normalizedWord.length + getFlatWordBonus();
    const lengthMultiplier = getLengthBonusMultiplier(normalizedWord);
    const discoveryBonus = options.isNewDiscovery ? getFirstDiscoveryBonus(normalizedWord) : 0;
    return Math.max(1, Math.floor((basePoints * lengthMultiplier * getWordIncomeMultiplier()) + discoveryBonus));
}


function getTotalRarityOwned(rarity) {
    return monkeyRoster.reduce((total, typeId) => {
        return total + (getMonkeyType(typeId).rarity === rarity ? 1 : 0);
    }, 0);
}

function getTotalSuperRaresOwned() {
    return getTotalRarityOwned('super-rare');
}

function getUnusedTypeIds(poolIds) {
    const safePoolIds = Array.isArray(poolIds) && poolIds.length > 0 ? poolIds : normalMonkeyTypeIds;
    const usedTypeIds = new Set(monkeyRoster.filter((typeId) => safePoolIds.includes(typeId)));
    const unused = safePoolIds.filter((typeId) => !usedTypeIds.has(typeId));
    return unused.length > 0 ? unused : safePoolIds;
}

function rollMonkeyRarity() {
    const legendaryChance = getLegendaryChance();
    const superRareChance = getSuperRareChance();
    const rareChance = getRareChance();
    const roll = Math.random();

    if (roll < legendaryChance) {
        return 'legendary';
    }

    if (roll < legendaryChance + superRareChance) {
        return 'super-rare';
    }

    if (roll < legendaryChance + superRareChance + rareChance) {
        return 'rare';
    }

    return 'normal';
}

function getRandomMonkeyTypeId() {
    const rarity = rollMonkeyRarity();
    const sourcePool = monkeyTypeIdsByRarity[rarity] || normalMonkeyTypeIds;
    return getRandomFromList(getUnusedTypeIds(sourcePool)) || getRandomFromList(normalMonkeyTypeIds);
}

function normalizeRosterEntry(entry) {
    if (typeof entry === 'string') {
        return MONKEY_TYPES.some((type) => type.id === entry) ? entry : getRandomFromList(normalMonkeyTypeIds);
    }

    if (entry && typeof entry === 'object' && typeof entry.typeId === 'string') {
        return MONKEY_TYPES.some((type) => type.id === entry.typeId) ? entry.typeId : getRandomFromList(normalMonkeyTypeIds);
    }

    return getRandomFromList(normalMonkeyTypeIds);
}

function getMonkeyRarityLabel(monkeyType) {
    return RARITY_CONFIG[monkeyType.rarity]?.label || 'Normal';
}

function getRarityClass(rarity) {
    return `is-${String(rarity || 'normal').replace(/[^a-z0-9-]/g, '')}`;
}

function getRarityBadge(rarity) {
    return RARITY_CONFIG[rarity]?.badge || '';
}

function getRarityLabelForGroup(rarity) {
    return RARITY_CONFIG[rarity]?.label.toLowerCase() || 'monkey';
}

function getMonkeySpriteSrc(monkeyType) {
    return MONKEY_SPRITE_DATA[monkeyType.sprite] || monkeyType.sprite;
}

function ensureMonkeyRosterMatchesCount() {
    if (!Array.isArray(monkeyRoster)) {
        monkeyRoster = [];
    }

    monkeyRoster = monkeyRoster.map(normalizeRosterEntry);

    while (monkeyRoster.length < monkeysOwned) {
        monkeyRoster.push(getRandomMonkeyTypeId());
    }

    if (monkeyRoster.length > monkeysOwned) {
        monkeyRoster = monkeyRoster.slice(0, monkeysOwned);
    }
}

function getDefaultLifetimeStats() {
    return {
        bananasEarned: 0,
        lettersTyped: 0,
        wordsFound: 0,
        monkeysHired: 0,
        upgradesPurchased: 0,
        questsClaimed: 0,
        officesUnlocked: 0,
        bestWord: '',
        bestWordPoints: 0,
        longestWord: '',
        raresHired: 0,
        superRaresHired: 0,
        legendaryHired: 0,
        uniqueWords: 0
    };
}

function normalizeLifetimeStats(rawStats = {}) {
    const defaults = getDefaultLifetimeStats();
    const normalized = { ...defaults, ...(rawStats || {}) };

    normalized.bananasEarned = Math.max(Number(normalized.bananasEarned) || 0, bananas);
    normalized.lettersTyped = Math.max(Number(normalized.lettersTyped) || 0, lettersTyped);
    normalized.wordsFound = Math.max(Number(normalized.wordsFound) || 0, wordsTyped);
    normalized.monkeysHired = Math.max(Number(normalized.monkeysHired) || 0, monkeysOwned);
    normalized.upgradesPurchased = Math.max(
        Number(normalized.upgradesPurchased) || 0,
        Object.values(upgrades).reduce((total, level) => total + (Number(level) || 0), 0)
    );
    normalized.questsClaimed = Math.max(
        Number(normalized.questsClaimed) || 0,
        claimedMilestones.filter((id) => {
            const entry = MILESTONES.find((milestone) => milestone.id === id);
            return entry && isQuestMilestone(entry);
        }).length
    );
    normalized.officesUnlocked = Math.max(Number(normalized.officesUnlocked) || 0, Math.max(0, officeLevel - 1));
    normalized.bestWord = typeof normalized.bestWord === 'string' ? normalized.bestWord : '';
    normalized.bestWordPoints = Math.max(Number(normalized.bestWordPoints) || 0, 0);
    normalized.longestWord = typeof normalized.longestWord === 'string' ? normalized.longestWord : '';
    normalized.raresHired = Math.max(Number(normalized.raresHired) || 0, getTotalRarityOwned('rare'));
    normalized.superRaresHired = Math.max(Number(normalized.superRaresHired) || 0, getTotalSuperRaresOwned());
    normalized.legendaryHired = Math.max(Number(normalized.legendaryHired) || 0, getTotalRarityOwned('legendary'));
    normalized.uniqueWords = Math.max(Number(normalized.uniqueWords) || 0, getDiscoveredWordCount());

    return normalized;
}

function addBananas(amount) {
    const bananaAmount = Math.max(0, Math.floor(Number(amount) || 0));
    bananas += bananaAmount;
    lifetimeStats.bananasEarned += bananaAmount;
    return bananaAmount;
}

function getTotalQuestClaims() {
    return claimedMilestones.filter((id) => {
        const entry = MILESTONES.find((milestone) => milestone.id === id);
        return entry && isQuestMilestone(entry);
    }).length;
}

function getTotalUpgradesPurchased() {
    return Object.values(upgrades).reduce((total, level) => total + (Number(level) || 0), 0);
}

function ensureProgressionState() {
    officeLevel = clamp(Number(officeLevel) || 1, 1, OFFICE_BUILDINGS.length);

    Object.keys(UPGRADE_DEFS).forEach((upgradeId) => {
        const level = Number(upgrades[upgradeId]) || 0;
        upgrades[upgradeId] = clamp(level, 0, UPGRADE_DEFS[upgradeId].maxLevel);
    });

    if (!Array.isArray(claimedMilestones)) {
        claimedMilestones = [];
    }

    const validMilestoneIds = new Set(MILESTONES.map((milestone) => milestone.id));
    claimedMilestones = [...new Set(claimedMilestones.map(String).filter((id) => validMilestoneIds.has(id)))];

    if (!Array.isArray(claimedCollectionRewards)) {
        claimedCollectionRewards = [];
    }

    const validCollectionRewardIds = new Set(COLLECTION_REWARDS.map((reward) => reward.id));
    claimedCollectionRewards = [...new Set(claimedCollectionRewards.map(String).filter((id) => validCollectionRewardIds.has(id)))];

    if (!Array.isArray(claimedOfficeRewards)) {
        claimedOfficeRewards = [];
    }

    const validOfficeRewardIds = new Set(OFFICE_BUILDINGS.map((office) => office.id));
    claimedOfficeRewards = [...new Set(claimedOfficeRewards.map(String).filter((id) => validOfficeRewardIds.has(id)))];

    discoveredWords = normalizeDiscoveredWords(discoveredWords);
    lifetimeStats = normalizeLifetimeStats(lifetimeStats);
    lifetimeStats.uniqueWords = getDiscoveredWordCount();
}

function syncOfficeVisuals(force = false) {
    const renderedMonkeyCount = monkeyOfficeGrid.querySelectorAll('[data-monkey-slot]').length;
    const hasEmptyState = Boolean(monkeyOfficeGrid.querySelector('.office-empty-state'));
    const renderSignature = getOfficeRenderSignature();

    if (force || renderSignature !== lastOfficeRenderSignature || renderedMonkeyCount !== monkeysOwned || (monkeysOwned === 0 && !hasEmptyState) || (monkeysOwned > 0 && hasEmptyState)) {
        renderMonkeyOffice();
        return;
    }

    monkeyOfficeSummary.textContent = monkeysOwned === 0
        ? 'No monkeys yet.'
        : `${formatNumber(monkeysOwned)} monkey${monkeysOwned === 1 ? '' : 's'} in office`;
}

function forceMonkeyOfficeRender() {
    ensureMonkeyRosterMatchesCount();
    renderMonkeyOffice();

    if (monkeysOwned > 0 && monkeyOfficeGrid.querySelectorAll('[data-monkey-slot]').length === 0) {
        requestAnimationFrame(() => renderMonkeyOffice());
        window.setTimeout(renderMonkeyOffice, 80);
    }
}

function getPlayerLevel() {
    return Math.max(1, Math.floor(lifetimeStats.wordsFound / 60) + officeLevel);
}

function getPassiveLetterRate() {
    if (monkeysOwned <= 0) {
        return 0;
    }
    let rate = 0;
    monkeyRoster.forEach((typeId) => {
        const monkeyType = getMonkeyType(typeId);
        const typeMultiplier = Math.max(1, Number(monkeyType.speedMultiplier) || 1);
        rate += typeMultiplier * getGlobalSpeedMultiplier() * (1000 / monkeyTypingIntervalMs);
    });
    return rate;
}

function getEstimatedWordRate() {
    return getPassiveLetterRate() / 5;
}

function getEstimatedBananaRate() {
    const avgPoints = Math.max(3, 3 + getFlatWordBonus());
    return getEstimatedWordRate() * avgPoints * getWordIncomeMultiplier();
}

function getAverageOfflineWordValue() {
    const averageWordLength = 4;
    const basePoints = averageWordLength + getFlatWordBonus();
    return Math.max(1, Math.floor(basePoints * getWordIncomeMultiplier()));
}

function getOfflineEarningsCapMs() {
    return clamp(baseOfflineCapMs + ((officeLevel - 1) * officeOfflineCapStepMs), baseOfflineCapMs, maxOfflineCapMs);
}

function calculateOfflineEarnings(elapsedMs) {
    const cappedElapsedMs = clamp(Number(elapsedMs) || 0, 0, getOfflineEarningsCapMs());
    const secondsAway = cappedElapsedMs / 1000;
    const passiveLetterRate = getPassiveLetterRate();
    const lettersTypedOffline = Math.floor(passiveLetterRate * secondsAway);
    const wordsFoundOffline = Math.floor(lettersTypedOffline / 32);
    const bananasEarnedOffline = wordsFoundOffline * getAverageOfflineWordValue();

    return {
        elapsedMs: Number(elapsedMs) || 0,
        cappedElapsedMs,
        capMs: getOfflineEarningsCapMs(),
        lettersTyped: lettersTypedOffline,
        wordsFound: wordsFoundOffline,
        bananasEarned: bananasEarnedOffline
    };
}

function getAffordableUpgradeCount() {
    return Object.keys(UPGRADE_DEFS).filter((upgradeId) => {
        const upgrade = UPGRADE_DEFS[upgradeId];
        const level = getUpgradeLevel(upgradeId);
        return level < upgrade.maxLevel && bananas >= getUpgradeCost(upgradeId);
    }).length;
}

function getReadyProgressionCount() {
    return getAffordableUpgradeCount() + (canAffordOfficeUnlock() ? 1 : 0) + getClaimableOfficeRewardCount();
}

function setDockBadge(badgeEl, count) {
    if (!badgeEl) {
        return;
    }

    const safeCount = Math.max(0, Math.floor(Number(count) || 0));
    badgeEl.textContent = String(safeCount);
    badgeEl.setAttribute('aria-hidden', safeCount > 0 ? 'false' : 'true');
    badgeEl.classList.toggle('is-pulsing', safeCount > 0);
}

function isQuestMilestone(milestone) {
    return milestone.category === 'quest';
}

function isLongTermMilestone(milestone) {
    return milestone.category !== 'quest';
}

function getUnlockedQuestTier() {
    if (officeLevel >= 4 || lifetimeStats.bananasEarned >= 250000 || getTotalQuestClaims() >= 20) {
        return 5;
    }

    if (officeLevel >= 3 || lifetimeStats.wordsFound >= 250 || getTotalQuestClaims() >= 14) {
        return 4;
    }

    if (officeLevel >= 2 || lifetimeStats.monkeysHired >= 8 || getTotalQuestClaims() >= 8) {
        return 3;
    }

    if (lifetimeStats.monkeysHired >= 3 || getTotalQuestClaims() >= 3 || lifetimeStats.bananasEarned >= 1000) {
        return 2;
    }

    return 1;
}

function getVisibleQuestPool() {
    const unlockedTier = getUnlockedQuestTier();
    return MILESTONES.filter((milestone) => isQuestMilestone(milestone) && (milestone.tier || 1) <= unlockedTier);
}

function getLockedQuestCount() {
    const unlockedTier = getUnlockedQuestTier();
    return MILESTONES.filter((milestone) => isQuestMilestone(milestone) && (milestone.tier || 1) > unlockedTier).length;
}

function getUnclaimedMilestones(category = null) {
    return MILESTONES.filter((milestone) => {
        if (category === 'quest') {
            return getVisibleQuestPool().includes(milestone) && !claimedMilestones.includes(milestone.id);
        }

        if (category === 'milestone' && !isLongTermMilestone(milestone)) {
            return false;
        }

        return !claimedMilestones.includes(milestone.id);
    });
}

function isMilestoneReady(milestone) {
    return getMilestoneProgress(milestone) >= milestone.target && !claimedMilestones.includes(milestone.id);
}

function sortProgressGoals(a, b) {
    const aReady = isMilestoneReady(a) ? 1 : 0;
    const bReady = isMilestoneReady(b) ? 1 : 0;

    if (aReady !== bReady) {
        return bReady - aReady;
    }

    const aRatio = clamp(getMilestoneProgress(a) / a.target, 0, 1);
    const bRatio = clamp(getMilestoneProgress(b) / b.target, 0, 1);

    if (aRatio !== bRatio) {
        return bRatio - aRatio;
    }

    return MILESTONES.indexOf(a) - MILESTONES.indexOf(b);
}

function getClaimableQuestCount() {
    return getVisibleQuestPool().filter((milestone) => isMilestoneReady(milestone)).length;
}

function getActiveQuestCount() {
    return getClaimableQuestCount();
}


function getQuestIconSrc(milestone) {
    switch (milestone.metric) {
        case 'letters':
        case 'lifetimeLetters':
            return 'icon-typewriter.png';
        case 'words':
        case 'lifetimeWords':
        case 'uniqueWords':
        case 'longestWordLength':
        case 'bestWordPoints':
            return 'icon-book.png';
        case 'monkeys':
        case 'totalMonkeysHired':
        case 'rares':
        case 'superRares':
        case 'legendaries':
            return 'icon-monkey.png';
        case 'officeLevel':
        case 'officesUnlocked':
        case 'upgrades':
        case 'totalUpgradesPurchased':
            return 'icon-upgrades.png';
        case 'bananas':
        case 'lifetimeBananas':
            return 'icon-bananas.png';
        case 'claimedQuests':
            return 'icon-quests.png';
        default:
            return 'icon-quests.png';
    }
}


function getOfficePerkBadges(office) {
    const perks = [];
    const incomePct = Math.round(((office.incomeMultiplier || 1) - 1) * 100);
    if (incomePct > 0) {
        perks.push({ icon: 'icon-bananas.png', text: `+${incomePct}% All Production` });
    }
    const speedPct = Math.round((office.speedBonus || 0) * 100);
    if (speedPct > 0) {
        perks.push({ icon: 'icon-typewriter.png', text: `+${speedPct}% Type Speed` });
    }
    if ((office.wordBonus || 0) > 0) {
        perks.push({ icon: 'icon-book.png', text: `+${office.wordBonus} Word Bonus` });
    }
    const rarePct = Math.round((0.10 + (office.rareBonus || 0)) * 100);
    perks.push({ icon: 'icon-clover.png', text: `${rarePct}% Rare Monkey Odds` });
    return perks;
}

function getOfficeCompletionPerkBadges() {
    const bonuses = getClaimedOfficeRewardBonuses();
    const perks = [];

    if (bonuses.speedBonus > 0) {
        perks.push({ icon: 'icon-typewriter.png', text: `+${Math.round(bonuses.speedBonus * 100)}% Chapter Speed` });
    }

    if (bonuses.incomeBonus > 0) {
        perks.push({ icon: 'icon-bananas.png', text: `+${Math.round(bonuses.incomeBonus * 100)}% Chapter Income` });
    }

    if (bonuses.flatWordBonus > 0) {
        perks.push({ icon: 'icon-book.png', text: `+${bonuses.flatWordBonus} Chapter Word Bonus` });
    }

    if (bonuses.rareBonus > 0) {
        perks.push({ icon: 'icon-clover.png', text: `+${Math.round(bonuses.rareBonus * 100)}% Chapter Rare Odds` });
    }

    return perks;
}

function normalizeRecentWords() {
    if (!Array.isArray(recentWords)) {
        recentWords = [];
    }

    recentWords = recentWords
        .filter((entry) => entry && typeof entry.word === 'string')
        .map((entry) => {
            const normalizedWord = entry.word.toLowerCase();
            return {
                word: normalizedWord,
                points: Math.max(1, Number(entry.points) || calculateWordPoints(normalizedWord)),
                newDiscovery: Boolean(entry.newDiscovery),
                bonusLabel: typeof entry.bonusLabel === 'string' ? entry.bonusLabel : ''
            };
        })
        .slice(0, recentWordLimit);
}


function renderRecentWords() {
    if (!recentWordsList) {
        return;
    }

    normalizeRecentWords();

    recentWordsList.replaceChildren();

    if (recentWords.length === 0) {
        const empty = document.createElement('span');
        empty.className = 'empty-state';
        empty.textContent = 'No words yet.';
        recentWordsList.appendChild(empty);
        return;
    }

    const fragment = document.createDocumentFragment();

    recentWords.slice(0, recentWordLimit).forEach((entry) => {
        const chip = document.createElement('span');
        chip.className = `recent-word ${entry.newDiscovery ? 'is-new-word' : ''} ${entry.bonusLabel ? 'has-word-bonus' : ''}`.trim();

        const word = document.createElement('span');
        word.className = 'recent-word-text';
        word.textContent = getDisplayWord(entry.word);

        const points = document.createElement('strong');
        points.textContent = `+${entry.points}`;

        chip.appendChild(word);
        points.appendChild(document.createTextNode(''));
        chip.appendChild(points);

        if (entry.newDiscovery || entry.bonusLabel) {
            const badge = document.createElement('em');
            badge.textContent = entry.newDiscovery ? 'NEW' : entry.bonusLabel;
            chip.appendChild(badge);
        }

        fragment.appendChild(chip);
    });

    recentWordsList.appendChild(fragment);
}


function updateDisplay() {
    const currentOffice = getCurrentOffice();

    bananasEl.textContent = formatUiNumber(bananas);
    lettersEl.textContent = formatUiNumber(lettersTyped);
    wordsEl.textContent = formatUiNumber(wordsTyped);
    monkeysEl.textContent = formatUiNumber(monkeysOwned);
    monkeyCostEl.textContent = formatDockCost(monkeyCost);
    monkeyCostInlineEl.textContent = formatDockCost(monkeyCost);

    if (bananasRateEl) bananasRateEl.textContent = `+${formatUiNumber(getEstimatedBananaRate())} /s`;
    if (lettersRateEl) lettersRateEl.textContent = `+${formatUiNumber(getPassiveLetterRate())} /s`;
    if (wordsRateEl) wordsRateEl.textContent = `+${formatUiNumber(getEstimatedWordRate())} /s`;
    if (monkeysRateEl) monkeysRateEl.textContent = monkeysOwned > 0 ? 'Crew' : 'None';
    if (playerLevelBadge) playerLevelBadge.textContent = `Lvl ${formatNumber(getPlayerLevel())}`;
    setDockBadge(questsBadge, getClaimableQuestCount());
    setDockBadge(upgradesBadge, getReadyProgressionCount());
    setDockBadge(collectionBadge, getClaimableCollectionRewardCount());

    officeLevelLabel.textContent = `Floor ${currentOffice.floor}`;
    officeNameTitle.textContent = currentOffice.name;

    buyMonkeyButton.disabled = bananas < monkeyCost;
    buyMonkeyButton.classList.toggle('can-afford', bananas >= monkeyCost);

    renderRecentWords();

    syncOfficeVisuals();
    updateProgressionPanel();
    dictionaryStatus.textContent = `${formatNumber(getDiscoveredWordCount())} discovered / ${formatNumber(getDictionaryWordCount())} dictionary words`;
}

function clearPlaceholder() {
    if (outputArea.querySelector('.placeholder')) {
        outputArea.innerHTML = '';
    }
}

function appendOutputLetter(letter, source = 'player') {
    clearPlaceholder();

    const charSpan = document.createElement('span');
    charSpan.className = source === 'monkey' ? 'typed-char monkey-char' : 'typed-char';
    charSpan.textContent = letter;
    outputArea.appendChild(charSpan);

    trimOutputArea();
}

function appendWordReward(word, points, isNewDiscovery = false, bonusLabel = '') {
    const wordSpan = document.createElement('span');
    wordSpan.className = `word-found ${isNewDiscovery ? 'is-new-word' : ''} ${bonusLabel ? 'has-word-bonus' : ''}`.trim();
    wordSpan.innerHTML = `
        <span>${getDisplayWord(word).toUpperCase()} +${points}</span>
        ${isNewDiscovery ? '<em>NEW</em>' : bonusLabel ? `<em>${bonusLabel}</em>` : ''}
        <span class="mini-banana-icon" aria-hidden="true"></span>
    `;
    outputArea.appendChild(wordSpan);

    trimOutputArea();
}


function trimOutputArea() {
    while (outputArea.childNodes.length > maxOutputNodes) {
        outputArea.removeChild(outputArea.firstChild);
    }

    outputArea.scrollTop = outputArea.scrollHeight;
}

function findNewWordsAtEnd() {
    const foundWords = [];
    const longestPossibleWord = Math.min(maxWordLength, typedStream.length);

    for (let length = minWordLength; length <= longestPossibleWord; length++) {
        const wordSet = wordsByLength.get(length);

        if (!wordSet) {
            continue;
        }

        const candidate = typedStream.slice(-length);

        if (wordSet.has(candidate)) {
            foundWords.push(candidate);
        }
    }

    return foundWords;
}

function spawnFloatingMessage(message, extraClass = '') {
    if (!floatingRewardsLayer) {
        return;
    }

    const reward = document.createElement('span');
    reward.className = `float-reward ${extraClass}`.trim();
    reward.textContent = message;
    reward.style.left = `${18 + Math.random() * 60}%`;
    reward.style.bottom = `${50 + Math.random() * 26}px`;
    floatingRewardsLayer.appendChild(reward);

    setTimeout(() => {
        reward.remove();
    }, 1250);
}

function spawnFloatingReward(points, word) {
    spawnFloatingMessage(`+${points} ${getDisplayWord(word).toUpperCase()}`);
}

function spawnHireBurst(extraClass = '') {
    if (!floatingRewardsLayer) {
        return;
    }

    for (let index = 0; index < 10; index += 1) {
        const burst = document.createElement('span');
        burst.className = `hire-burst-piece ${extraClass}`.trim();
        burst.style.left = `${28 + Math.random() * 44}%`;
        burst.style.top = `${26 + Math.random() * 32}%`;
        burst.style.setProperty('--burst-x', `${(Math.random() - 0.5) * 150}px`);
        burst.style.setProperty('--burst-y', `${-36 - Math.random() * 82}px`);
        burst.style.animationDelay = `${index * 22}ms`;
        floatingRewardsLayer.appendChild(burst);

        setTimeout(() => burst.remove(), 900);
    }
}

function triggerScreenShake(strength = 'normal') {
    if (!appRoot) {
        return;
    }

    appRoot.classList.remove('is-shaking', 'is-big-shake');
    void appRoot.offsetWidth;
    appRoot.classList.add(strength === 'big' ? 'is-big-shake' : 'is-shaking');
    window.setTimeout(() => appRoot.classList.remove('is-shaking', 'is-big-shake'), 520);
}

function showCelebration(kicker, title, detail = '', type = 'reward', options = {}) {
    if (!celebrationOverlay) {
        return;
    }

    if (activeCelebrationTimeout) {
        clearTimeout(activeCelebrationTimeout);
        activeCelebrationTimeout = null;
    }

    celebrationOverlay.replaceChildren();
    celebrationOverlay.className = `celebration-overlay is-visible is-${type}`;
    celebrationOverlay.setAttribute('aria-hidden', 'false');

    const card = document.createElement('div');
    card.className = 'celebration-card';

    const kickerEl = document.createElement('span');
    kickerEl.className = 'celebration-kicker';
    kickerEl.textContent = kicker;

    const titleEl = document.createElement('strong');
    titleEl.textContent = title;

    card.appendChild(kickerEl);
    card.appendChild(titleEl);

    if (detail) {
        const detailEl = document.createElement('p');
        detailEl.textContent = detail;
        card.appendChild(detailEl);
    }

    celebrationOverlay.appendChild(card);

    if (options.burst !== false) {
        spawnHireBurst(`is-${type}`);
    }

    if (options.shake) {
        triggerScreenShake(options.shake === 'big' ? 'big' : 'normal');
    }

    activeCelebrationTimeout = window.setTimeout(() => {
        celebrationOverlay.classList.remove('is-visible');
        celebrationOverlay.setAttribute('aria-hidden', 'true');
        activeCelebrationTimeout = window.setTimeout(() => {
            celebrationOverlay.replaceChildren();
            activeCelebrationTimeout = null;
        }, 240);
    }, options.duration || 1700);
}

function showOfflineWelcome(summary) {
    if (!summary || summary.bananasEarned <= 0) {
        return;
    }

    const cappedText = summary.elapsedMs > summary.cappedElapsedMs ? ' • offline cap reached' : '';
    showCelebration(
        'Welcome back!',
        `+${formatNumber(summary.bananasEarned)} bananas`,
        `Your monkeys typed ${formatNumber(summary.lettersTyped)} letters, found ${formatNumber(summary.wordsFound)} words${cappedText}.`,
        'offline',
        { duration: 2600, shake: false }
    );
}

function applyOfflineEarnings(summary, options = {}) {
    if (!summary || summary.lettersTyped <= 0) {
        return false;
    }

    lettersTyped += summary.lettersTyped;
    lifetimeStats.lettersTyped += summary.lettersTyped;
    wordsTyped += summary.wordsFound;
    lifetimeStats.wordsFound += summary.wordsFound;

    if (summary.bananasEarned > 0) {
        addBananas(summary.bananasEarned);
    }

    spawnFloatingMessage(`AWAY +${formatNumber(summary.bananasEarned)} BANANAS`, 'is-offline');

    if (options.showSummary) {
        showOfflineWelcome(summary);
    }

    return true;
}

function processOfflineEarnings(options = {}) {
    const now = Date.now();
    const elapsedMs = now - (Number(lastActiveAt) || now);
    lastActiveAt = now;

    if (elapsedMs < offlineMinimumMs || monkeysOwned <= 0) {
        saveGame();
        return null;
    }

    const summary = calculateOfflineEarnings(elapsedMs);
    if (summary.lettersTyped <= 0 || summary.wordsFound <= 0 || summary.bananasEarned <= 0) {
        saveGame();
        return summary;
    }

    applyOfflineEarnings(summary, { showSummary: Boolean(options.showSummary) });
    updateDisplay();
    saveGame();
    return summary;
}

function showNewHireReveal(monkeyType, isNewType = false) {
    if (!floatingRewardsLayer) {
        return;
    }

    const rarity = monkeyType.rarity || 'normal';
    const rarityClass = getRarityClass(rarity);
    const isSpecialRarity = rarity !== 'normal';
    const reveal = document.createElement('div');
    reveal.className = `hire-reveal-card ${rarityClass} ${isNewType ? 'is-new-type' : ''}`.trim();
    reveal.innerHTML = `
        <div class="hire-reveal-badges">
            <span>New Hire!</span>
            ${isNewType ? '<span class="is-new-badge">NEW</span>' : ''}
            ${isSpecialRarity ? `<span class="is-rare-badge">${getMonkeyRarityLabel(monkeyType)}!</span>` : ''}
        </div>
        <div class="hire-reveal-main">
            <div class="hire-reveal-art"><img src="${getMonkeySpriteSrc(monkeyType)}" alt="" onerror="this.onerror=null; this.src='icon-monkey.png';" /></div>
            <div class="hire-reveal-copy">
                <strong>${monkeyType.name}</strong>
                <span>${getMonkeyRarityLabel(monkeyType)}</span>
                <em>${monkeyType.speedMultiplier}x typing speed</em>
            </div>
        </div>
    `;

    floatingRewardsLayer.appendChild(reveal);
    spawnHireBurst(isSpecialRarity ? rarityClass : '');

    setTimeout(() => reveal.remove(), rarity === 'legendary' ? 3200 : rarity === 'super-rare' ? 2300 : rarity === 'rare' ? 2050 : 1850);
}

function spawnMonkeyHireMessage(monkeyType, isNewType = false) {
    const rarity = monkeyType.rarity || 'normal';
    const rarityClass = getRarityClass(rarity);
    const prefix = rarity === 'legendary' ? 'LEGENDARY' : rarity === 'super-rare' ? 'SUPER RARE' : rarity === 'rare' ? 'RARE' : 'HIRED';
    const badge = getRarityBadge(rarity);
    showNewHireReveal(monkeyType, isNewType);
    spawnFloatingMessage(`${prefix}: ${monkeyType.name.toUpperCase()}${badge ? ` ${badge}` : ''}`, rarity === 'normal' ? 'is-hire' : rarityClass);
}

function awardWords(words) {
    words.forEach((word) => {
        const normalizedWord = String(word).toLowerCase();
        const isNewDiscovery = !hasDiscoveredWord(normalizedWord);
        const bonusLabel = getLengthBonusLabel(normalizedWord);
        const points = calculateWordPoints(normalizedWord, { isNewDiscovery });

        if (isNewDiscovery) {
            markDiscoveredWord(normalizedWord);
        }

        addBananas(points);
        wordsTyped += 1;
        lifetimeStats.wordsFound += 1;

        if (points > lifetimeStats.bestWordPoints) {
            lifetimeStats.bestWordPoints = points;
            lifetimeStats.bestWord = normalizedWord;
        }

        if (normalizedWord.length > lifetimeStats.longestWord.length) {
            lifetimeStats.longestWord = normalizedWord;
        }

        recentWords = recentWords.filter((entry) => entry.word !== normalizedWord);
        recentWords.unshift({ word: normalizedWord, points, newDiscovery: isNewDiscovery, bonusLabel });
        appendWordReward(normalizedWord, points, isNewDiscovery, bonusLabel);

        if (isNewDiscovery) {
            spawnFloatingMessage(`NEW WORD: ${getDisplayWord(normalizedWord).toUpperCase()}`, 'is-super-rare');
            showCelebration('New Word Discovered!', normalizedWord.toUpperCase(), `+${formatNumber(points)} bananas`, 'word', { duration: 1350, burst: normalizedWord.length >= 5 });
        }

        if (bonusLabel) {
            spawnFloatingMessage(`${bonusLabel} WORD +${formatNumber(points)}`, 'is-hire');
            if (normalizedWord.length >= 6) {
                showCelebration('Long Word Jackpot!', normalizedWord.toUpperCase(), `${bonusLabel} • +${formatNumber(points)} bananas`, 'jackpot', { duration: 1750, shake: normalizedWord.length >= 7 ? 'big' : 'normal' });
            }
        }

        spawnFloatingReward(points, normalizedWord);
    });

    recentWords = recentWords.slice(0, recentWordLimit);
    renderRecentWords();
}

function animateMonkey(monkeyIndex, letter) {
    if (monkeysOwned <= 0) {
        return;
    }

    let targetIndex = typeof monkeyIndex === 'number' ? monkeyIndex : Math.floor(Math.random() * monkeysOwned);

    if (targetIndex < 0 || targetIndex >= monkeysOwned) {
        targetIndex = Math.floor(Math.random() * monkeysOwned);
    }

    const monkeyEl = monkeyOfficeGrid.querySelector(`[data-monkey-slot="${targetIndex}"]`);
    if (!monkeyEl) {
        return;
    }

    const bubble = monkeyEl.querySelector('.letter-bubble');
    if (bubble) {
        bubble.textContent = String(letter).toUpperCase();
    }

    monkeyEl.classList.remove('typing');
    void monkeyEl.offsetWidth;
    monkeyEl.classList.add('typing');

    if (monkeyAnimationTimeouts.has(targetIndex)) {
        clearTimeout(monkeyAnimationTimeouts.get(targetIndex));
    }

    const timeoutId = setTimeout(() => {
        monkeyEl.classList.remove('typing');
        if (bubble) {
            bubble.textContent = '';
        }
        monkeyAnimationTimeouts.delete(targetIndex);
    }, monkeyAnimationDurationMs);

    monkeyAnimationTimeouts.set(targetIndex, timeoutId);
}

function getMonkeyTypingDelay(typeId) {
    const monkeyType = getMonkeyType(typeId);
    const typeMultiplier = Math.max(1, Number(monkeyType.speedMultiplier) || 1);
    const totalMultiplier = Math.max(0.25, typeMultiplier * getGlobalSpeedMultiplier());

    // A normal monkey types about once every 2 seconds.
    // Super rare monkeys and upgrades reduce this delay.
    return Math.max(250, monkeyTypingIntervalMs / totalMultiplier);
}

function getOfficeCrewRowCount(total) {
    if (total <= 4) {
        return 1;
    }

    if (total <= 6) {
        return 2;
    }

    return total > 24 ? maxOfficeCrewRows : 2;
}

function getOfficeStageLayout(total) {
    const safeTotal = Math.max(0, Number(total) || 0);
    const isScrolling = safeTotal >= officeScrollStartCount;
    const rows = getOfficeCrewRowCount(safeTotal);
    const columns = Math.max(1, Math.ceil(safeTotal / Math.max(1, rows)));

    if (!isScrolling) {
        return {
            rows,
            columns,
            stageWidth: 100,
            panOffset: 0,
            duration: 0,
            isScrolling: false
        };
    }

    // The pan track must be visibly wider than the clipped office viewport.
    // v36 used a smaller track and long pauses, which made the camera feel stuck.
    const rowAdjustedVisibleColumns = rows >= 3 ? visibleOfficeColumns - 0.15 : visibleOfficeColumns;
    const stageWidth = clamp(Math.ceil((columns / rowAdjustedVisibleColumns) * 100), 156, 720);
    const panOffset = -(((stageWidth - 100) / stageWidth) * 100);
    const duration = clamp(12 + (columns * 2.05), 18, 42);

    return {
        rows,
        columns,
        stageWidth,
        panOffset,
        duration,
        isScrolling: true
    };
}

function getMonkeySeat(index, total) {
    const layouts = {
        1: [{ x: 50, y: 12, scale: 1.1 }],
        2: [{ x: 38, y: 12, scale: 1.02 }, { x: 62, y: 12, scale: 1.02 }],
        3: [{ x: 24, y: 13, scale: .92 }, { x: 50, y: 14, scale: 1.04 }, { x: 76, y: 13, scale: .92 }],
        4: [{ x: 18, y: 13, scale: .88 }, { x: 40, y: 15, scale: .96 }, { x: 60, y: 15, scale: .96 }, { x: 82, y: 13, scale: .88 }],
        5: [{ x: 24, y: 29, scale: .88 }, { x: 50, y: 31, scale: .96 }, { x: 76, y: 29, scale: .88 }, { x: 37, y: 11, scale: .96 }, { x: 63, y: 11, scale: .96 }],
        6: [{ x: 22, y: 30, scale: .86 }, { x: 50, y: 32, scale: .94 }, { x: 78, y: 30, scale: .86 }, { x: 26, y: 11, scale: .92 }, { x: 50, y: 12, scale: .98 }, { x: 74, y: 11, scale: .92 }]
    };

    if (total <= 6) {
        const seats = layouts[Math.max(1, total)] || layouts[6];
        return seats[index % seats.length];
    }

    const layout = getOfficeStageLayout(total);
    const row = index % layout.rows;
    const col = Math.floor(index / layout.rows);
    const x = ((col + 0.5) / layout.columns) * 100;
    const rowProfiles = layout.rows === 3
        ? [
            { y: 10, scale: .82 },
            { y: 30, scale: .74 },
            { y: 50, scale: .66 }
        ]
        : [
            { y: 12, scale: .90 },
            { y: 38, scale: .76 }
        ];
    const profile = rowProfiles[row] || rowProfiles[rowProfiles.length - 1];
    const stagger = col % 2 === 0 ? 0 : 2;

    return {
        x,
        y: profile.y + (row === 0 ? stagger * 0.35 : stagger),
        scale: profile.scale
    };
}

function getMonkeySeatStyle(index, total) {
    const seat = getMonkeySeat(index, total);
    const zIndex = Math.max(2, Math.round(120 - seat.y + index * 0.01));
    return `--seat-x:${seat.x}%; --seat-y:${seat.y}%; --seat-scale:${seat.scale}; --seat-z:${zIndex};`;
}

function getOfficeRenderSignature() {
    ensureMonkeyRosterMatchesCount();
    return [officeLevel, monkeysOwned, monkeyRoster.join(',')].join('|');
}

function typeRandomLetter(source = 'player', monkeyIndex = null) {
    const randomLetter = alphabet[Math.floor(Math.random() * alphabet.length)];

    typedStream += randomLetter;
    if (typedStream.length > maxSavedStreamLength) {
        typedStream = typedStream.slice(-maxSavedStreamLength);
    }

    lettersTyped += 1;
    lifetimeStats.lettersTyped += 1;
    appendOutputLetter(randomLetter, source);
    animateMonkey(monkeyIndex, randomLetter);

    const foundWords = findNewWordsAtEnd();
    if (foundWords.length > 0) {
        awardWords(foundWords);
    }

    updateDisplay();
    saveGame();
}

function buyMonkey() {
    if (bananas < monkeyCost) {
        return;
    }

    bananas -= monkeyCost;
    monkeysOwned += 1;
    lifetimeStats.monkeysHired += 1;

    const hiredTypeId = getRandomMonkeyTypeId();
    const isNewMonkeyType = !getOwnedMonkeyTypeIds().has(hiredTypeId);
    monkeyRoster.push(hiredTypeId);
    const hiredMonkeyType = getMonkeyType(hiredTypeId);
    if (hiredMonkeyType.rarity === 'rare') {
        lifetimeStats.raresHired += 1;
    }
    if (hiredMonkeyType.rarity === 'super-rare') {
        lifetimeStats.superRaresHired += 1;
    }
    if (hiredMonkeyType.rarity === 'legendary') {
        lifetimeStats.legendaryHired += 1;
    }
    const newMonkeyIndex = monkeysOwned - 1;

    monkeyCost = Math.ceil(monkeyCost * 1.9);

    forceMonkeyOfficeRender();
    updateDisplay();
    saveGame();
    spawnMonkeyHireMessage(hiredMonkeyType, isNewMonkeyType);
    if (hiredMonkeyType.rarity === 'rare') {
        showCelebration('Rare Hire!', hiredMonkeyType.name, `${hiredMonkeyType.speedMultiplier}x typing speed`, 'rare', { duration: 1800 });
    }
    if (hiredMonkeyType.rarity === 'super-rare') {
        showCelebration('Super Rare Hire!', hiredMonkeyType.name, `${hiredMonkeyType.speedMultiplier}x typing speed`, 'super-rare', { duration: 2300, shake: 'big' });
    }
    if (hiredMonkeyType.rarity === 'legendary') {
        showCelebration('Legendary Hire!', hiredMonkeyType.name, `${hiredMonkeyType.speedMultiplier}x typing speed`, 'legendary', { duration: 3200, shake: 'big' });
    }

    // Prime the new hire and keep every existing monkey on its own two-second schedule.
    primeMonkeyForTyping(newMonkeyIndex, 450);
    startMonkeyTypingEngine(true);

    requestAnimationFrame(() => {
        forceMonkeyOfficeRender();
        animateMonkey(newMonkeyIndex, getRarityBadge(hiredMonkeyType.rarity) || '!');
        primeMonkeyForTyping(newMonkeyIndex, 450);
        startMonkeyTypingEngine(true);
    });
}

function clearPendingMonkeyTyping() {
    pendingMonkeyTypeTimeouts.forEach((timeoutId) => clearTimeout(timeoutId));
    pendingMonkeyTypeTimeouts = [];
}

function stopMonkeyTypingEngine() {
    if (monkeyTypingEngineId) {
        clearInterval(monkeyTypingEngineId);
        monkeyTypingEngineId = null;
    }

    clearPendingMonkeyTyping();
    monkeyNextTypeAt = [];

    if (monkeyTypingWatchdogId) {
        clearInterval(monkeyTypingWatchdogId);
        monkeyTypingWatchdogId = null;
    }
}

function syncMonkeyTypingSchedule(now = performance.now(), runSoon = false) {
    ensureMonkeyRosterMatchesCount();

    if (monkeyNextTypeAt.length > monkeysOwned) {
        monkeyNextTypeAt = monkeyNextTypeAt.slice(0, monkeysOwned);
    }

    while (monkeyNextTypeAt.length < monkeysOwned) {
        const monkeyIndex = monkeyNextTypeAt.length;
        const typeId = monkeyRoster[monkeyIndex];
        const stagger = runSoon ? 350 + (monkeyIndex % 6) * 130 : getMonkeyTypingDelay(typeId);
        monkeyNextTypeAt.push(now + stagger);
    }

    if (runSoon && monkeysOwned > 0) {
        monkeyNextTypeAt = monkeyNextTypeAt.map((nextAt, index) => {
            const stagger = 350 + (index % 6) * 130;
            return Math.min(Number(nextAt) || Infinity, now + stagger);
        });
    }
}

function primeMonkeyForTyping(monkeyIndex, delayMs = 450) {
    if (monkeyIndex == null || monkeyIndex < 0) {
        return;
    }

    const now = performance.now();
    syncMonkeyTypingSchedule(now, false);
    monkeyNextTypeAt[monkeyIndex] = now + delayMs;
}

function startMonkeyTypingEngine(runSoon = false) {
    const now = performance.now();
    syncMonkeyTypingSchedule(now, runSoon);

    if (!monkeyTypingEngineId) {
        // A short scheduler tick is more reliable on mobile Safari than chaining requestAnimationFrame
        // for a background idle mechanic. Each monkey still has its own ~2s due time.
        monkeyTypingEngineId = setInterval(() => runMonkeyTyping(performance.now()), 250);
    }

    if (runSoon) {
        window.setTimeout(() => runMonkeyTyping(performance.now()), 80);
    }
}

function runMonkeyTyping(timestamp = performance.now()) {
    if (monkeysOwned <= 0) {
        clearPendingMonkeyTyping();
        monkeyNextTypeAt = [];
        return;
    }

    ensureMonkeyRosterMatchesCount();

    if (monkeyOfficeGrid.querySelectorAll('[data-monkey-slot]').length !== monkeysOwned) {
        renderMonkeyOffice();
    }

    syncMonkeyTypingSchedule(timestamp, false);

    monkeyRoster.forEach((typeId, index) => {
        const delay = getMonkeyTypingDelay(typeId);
        const nextAt = Number(monkeyNextTypeAt[index]) || (timestamp + delay);

        if (timestamp >= nextAt) {
            typeRandomLetter('monkey', index);

            // Schedule the next keystroke from now so a paused tab never dumps a burst of catch-up letters.
            monkeyNextTypeAt[index] = timestamp + delay;
        }
    });
}

function renderMonkeyOffice() {
    ensureMonkeyRosterMatchesCount();

    monkeyOfficeGrid.classList.remove('is-scrolling-office', 'is-two-row-office', 'is-three-row-office');
    monkeyOfficeGrid.style.removeProperty('--office-stage-width');
    monkeyOfficeGrid.style.removeProperty('--office-pan-offset');
    monkeyOfficeGrid.style.removeProperty('--office-pan-duration');

    if (monkeysOwned === 0) {
        lastOfficeRenderSignature = getOfficeRenderSignature();
        monkeyOfficeSummary.textContent = 'No monkeys yet.';
        monkeyOfficeGrid.innerHTML = `
            <div class="office-empty-state">
                <div class="empty-circle" aria-hidden="true"></div>
                <strong>Hire your first monkey</strong>
            </div>
        `;
        return;
    }

    const layout = getOfficeStageLayout(monkeysOwned);
    const rowClass = layout.rows >= 3 ? 'is-three-row-office' : layout.rows === 2 ? 'is-two-row-office' : '';
    monkeyOfficeGrid.classList.toggle('is-scrolling-office', layout.isScrolling);
    if (rowClass) {
        monkeyOfficeGrid.classList.add(rowClass);
    }
    monkeyOfficeGrid.style.setProperty('--office-stage-width', `${layout.stageWidth}%`);
    monkeyOfficeGrid.style.setProperty('--office-pan-offset', `${layout.panOffset.toFixed(3)}%`);
    monkeyOfficeGrid.style.setProperty('--office-pan-duration', `${layout.duration}s`);

    lastOfficeRenderSignature = getOfficeRenderSignature();
    monkeyOfficeSummary.textContent = `${formatNumber(monkeysOwned)} monkey${monkeysOwned === 1 ? '' : 's'} in office`;
    monkeyOfficeGrid.innerHTML = `
        <div class="monkey-office-pan" data-office-pan-columns="${layout.columns}" style="--office-stage-width:${layout.stageWidth}%; --office-pan-offset:${layout.panOffset.toFixed(3)}%; --office-pan-duration:${layout.duration}s;">
            ${monkeyRoster
                .map((typeId, index) => {
                    const monkeyType = getMonkeyType(typeId);
                    const rarityClass = ` ${getRarityClass(monkeyType.rarity)}`;
                    const rarityLabel = getMonkeyRarityLabel(monkeyType);
                    const rarityBadgeText = getRarityBadge(monkeyType.rarity);
                    const speedLabel = `${monkeyType.speedMultiplier}x speed`;
                    const rarityBadge = rarityBadgeText
                        ? `<span class="monkey-rarity-star" aria-hidden="true">${rarityBadgeText}</span>`
                        : '';

                    return `
                        <div class="office-monkey${rarityClass}" data-monkey-slot="${index}" style="${getMonkeySeatStyle(index, monkeysOwned)}" title="${monkeyType.name} — ${rarityLabel} • ${speedLabel}" aria-label="${monkeyType.name}, ${rarityLabel}, ${speedLabel}">
                            <span class="letter-bubble" aria-hidden="true"></span>
                            ${rarityBadge}
                            <div class="office-monkey-art">
                                <img src="${getMonkeySpriteSrc(monkeyType)}" alt="" class="monkey-sprite" loading="eager" decoding="async" onerror="this.onerror=null; this.src=\'icon-monkey.png\'; this.classList.add(\'is-fallback-sprite\');" />
                            </div>
                        </div>
                    `;
                })
                .join('')}
        </div>
    `;
}

function getMilestoneProgress(milestone) {
    switch (milestone.metric) {
        case 'letters':
            return lettersTyped;
        case 'lifetimeLetters':
            return lifetimeStats.lettersTyped;
        case 'words':
            return wordsTyped;
        case 'lifetimeWords':
            return lifetimeStats.wordsFound;
        case 'uniqueWords':
            return getDiscoveredWordCount();
        case 'monkeys':
            return monkeysOwned;
        case 'totalMonkeysHired':
            return lifetimeStats.monkeysHired;
        case 'rares':
            return Math.max(getTotalRarityOwned('rare'), lifetimeStats.raresHired);
        case 'superRares':
            return Math.max(getTotalSuperRaresOwned(), lifetimeStats.superRaresHired);
        case 'legendaries':
            return Math.max(getTotalRarityOwned('legendary'), lifetimeStats.legendaryHired);
        case 'officeLevel':
            return officeLevel;
        case 'officesUnlocked':
            return lifetimeStats.officesUnlocked;
        case 'upgrades':
        case 'totalUpgradesPurchased':
            return Math.max(getTotalUpgradesPurchased(), lifetimeStats.upgradesPurchased);
        case 'claimedQuests':
            return Math.max(getTotalQuestClaims(), lifetimeStats.questsClaimed);
        case 'bananas':
            return bananas;
        case 'lifetimeBananas':
            return lifetimeStats.bananasEarned;
        case 'bestWordPoints':
            return lifetimeStats.bestWordPoints;
        case 'longestWordLength':
            return lifetimeStats.longestWord.length;
        default:
            return 0;
    }
}

function getRequirementProgress(requirement) {
    return getMilestoneProgress({ metric: requirement.metric, target: requirement.target });
}

function getOfficeProgressStatus(items = []) {
    return (Array.isArray(items) ? items : []).map((item) => {
        const progress = getRequirementProgress(item);
        return {
            ...item,
            progress,
            complete: progress >= item.target,
            ratio: clamp(progress / item.target, 0, 1)
        };
    });
}

function getOfficeRequirementStatus(office) {
    return getOfficeProgressStatus(office && office.requirements);
}

function getOfficeGoalStatus(office) {
    return getOfficeProgressStatus(office && office.goals);
}

function isOfficeUnlocked(office) {
    return Boolean(office && office.floor <= officeLevel);
}

function getOfficeCompletionPercent(office) {
    const goals = getOfficeGoalStatus(office);
    if (goals.length === 0) {
        return 100;
    }

    const totalRatio = goals.reduce((total, goal) => total + goal.ratio, 0);
    return Math.round((totalRatio / goals.length) * 100);
}

function hasCompletedOfficeGoals(office) {
    const goals = getOfficeGoalStatus(office);
    return goals.length > 0 && goals.every((goal) => goal.complete);
}

function hasClaimedOfficeReward(office) {
    return Boolean(office && claimedOfficeRewards.includes(office.id));
}

function canClaimOfficeReward(office) {
    return isOfficeUnlocked(office) && hasCompletedOfficeGoals(office) && !hasClaimedOfficeReward(office);
}

function getClaimableOfficeRewardCount() {
    return OFFICE_BUILDINGS.filter((office) => canClaimOfficeReward(office)).length;
}

function meetsOfficeRequirements(office) {
    return getOfficeRequirementStatus(office).every((requirement) => requirement.complete);
}

function getOfficeRequirementMessage(office) {
    const incomplete = getOfficeRequirementStatus(office).filter((requirement) => !requirement.complete);
    if (incomplete.length === 0) {
        return '';
    }

    const first = incomplete[0];
    return `${first.label}: ${formatNumber(Math.min(first.progress, first.target))}/${formatNumber(first.target)}`;
}

function renderOfficeStatusList(items, emptyLabel, className = 'office-requirements') {
    if (items.length === 0) {
        return `<div class="${className}"><span class="office-requirement is-complete">${emptyLabel}</span></div>`;
    }

    return `
        <div class="${className}">
            ${items.map((item) => `
                <span class="office-requirement ${item.complete ? 'is-complete' : ''}">
                    ${item.complete ? '✓' : '•'} ${item.label} <em>${formatNumber(Math.min(item.progress, item.target))}/${formatNumber(item.target)}</em>
                </span>
            `).join('')}
        </div>
    `;
}

function renderOfficeRequirements(office) {
    return renderOfficeStatusList(getOfficeRequirementStatus(office), 'Ready to unlock', 'office-requirements');
}

function renderOfficeGoals(office) {
    return renderOfficeStatusList(getOfficeGoalStatus(office), 'No chapter goals', 'office-requirements office-goals');
}

function getOfficeCompletionRewardText(office) {
    return (office && (office.rewardLabel || getCollectionRewardBonusText(office.completionReward))) || 'Permanent bonus';
}

function getOfficeStateLabel(office) {
    if (hasClaimedOfficeReward(office)) {
        return 'Complete';
    }

    if (!isOfficeUnlocked(office)) {
        return 'Locked';
    }

    if (canClaimOfficeReward(office)) {
        return 'Ready';
    }

    return 'Unlocked';
}

function getOfficeRewardButtonLabel(office) {
    if (!isOfficeUnlocked(office)) {
        return 'Locked';
    }

    if (hasClaimedOfficeReward(office)) {
        return 'Bonus Earned';
    }

    if (canClaimOfficeReward(office)) {
        return 'Claim Bonus';
    }

    return 'In Progress';
}

function renderOfficeCompletionCard(office, options = {}) {
    const goals = getOfficeGoalStatus(office);
    const percent = getOfficeCompletionPercent(office);
    const isUnlocked = isOfficeUnlocked(office);
    const isClaimed = hasClaimedOfficeReward(office);
    const isReady = canClaimOfficeReward(office);
    const isCurrent = office.id === getCurrentOffice().id;
    const stateLabel = getOfficeStateLabel(office);
    const showDescription = options.showDescription !== false;

    return `
        <article class="progress-card office-chapter-card ${isCurrent ? 'is-current-office' : ''} ${isUnlocked ? 'is-unlocked-office' : 'is-locked-office'} ${isClaimed ? 'is-complete-office' : ''} ${isReady ? 'is-ready' : ''}">
            <div class="progress-card-copy">
                <span class="progress-branch">Floor ${office.floor} • ${stateLabel}</span>
                <h3>${office.name}</h3>
                ${showDescription ? `<p>${office.description}</p>` : ''}
                <div class="office-completion-meter">
                    <div>
                        <strong>${percent}%</strong>
                        <span>Chapter Complete</span>
                    </div>
                    <div class="milestone-bar" aria-hidden="true"><span style="width: ${percent}%"></span></div>
                </div>
                <div class="office-card-subhead">Office Goals</div>
                ${renderOfficeGoals(office)}
                <div class="office-reward-row ${isClaimed ? 'is-earned' : ''}">
                    <span>Permanent Bonus</span>
                    <strong>${getOfficeCompletionRewardText(office)}</strong>
                </div>
            </div>
            <button type="button" class="progress-buy-button office-reward-button" data-office-reward-id="${office.id}" ${!isReady ? 'disabled' : ''}>
                ${getOfficeRewardButtonLabel(office)}
            </button>
        </article>
    `;
}


function buyUpgrade(upgradeId) {
    const upgrade = UPGRADE_DEFS[upgradeId];
    if (!upgrade) {
        return;
    }

    const currentLevel = getUpgradeLevel(upgradeId);
    if (currentLevel >= upgrade.maxLevel) {
        return;
    }

    const cost = getUpgradeCost(upgradeId);
    if (bananas < cost) {
        return;
    }

    bananas -= cost;
    upgrades[upgradeId] = currentLevel + 1;
    lifetimeStats.upgradesPurchased += 1;
    spawnFloatingMessage(`${upgrade.name.toUpperCase()} +1`, 'is-hire');
    updateDisplay();
    saveGame();
}

function unlockNextOffice() {
    const nextOffice = getNextOffice();
    if (!nextOffice) {
        spawnFloatingMessage('ALL OFFICES UNLOCKED', 'is-hire');
        return;
    }

    if (!meetsOfficeRequirements(nextOffice)) {
        const requirementMessage = getOfficeRequirementMessage(nextOffice);
        spawnFloatingMessage(requirementMessage ? requirementMessage.toUpperCase() : 'FINISH OFFICE GOALS FIRST', 'is-hire');
        updateProgressionPanel();
        return;
    }

    if (bananas < nextOffice.unlockCost) {
        const needed = nextOffice.unlockCost - bananas;
        spawnFloatingMessage(`NEED ${formatNumber(needed)} MORE BANANAS`, 'is-hire');
        updateProgressionPanel();
        return;
    }

    bananas -= nextOffice.unlockCost;
    officeLevel = clamp(officeLevel + 1, 1, OFFICE_BUILDINGS.length);
    lifetimeStats.officesUnlocked = Math.max(lifetimeStats.officesUnlocked, officeLevel - 1);
    spawnFloatingMessage(`${nextOffice.name.toUpperCase()} UNLOCKED`, 'is-super-rare');
    showCelebration('Office Unlocked!', nextOffice.name, `Floor ${nextOffice.floor}`, 'office', { duration: 2100, shake: 'normal' });
    updateDisplay();
    saveGame();
}


function claimMilestone(milestoneId) {
    const normalizedId = String(milestoneId || '');
    const milestone = MILESTONES.find((entry) => entry.id === normalizedId);
    if (!milestone || claimedMilestones.includes(normalizedId)) {
        return;
    }

    if (getMilestoneProgress(milestone) < milestone.target) {
        updateProgressionPanel();
        return;
    }

    claimedMilestones.push(normalizedId);
    if (isQuestMilestone(milestone)) {
        lifetimeStats.questsClaimed += 1;
    }
    addBananas(milestone.reward);
    const isQuestReward = isQuestMilestone(milestone);
    spawnFloatingMessage(`GOAL +${formatNumber(milestone.reward)} BANANAS`, 'is-hire');
    showCelebration(
        isQuestReward ? 'Quest Complete!' : 'Milestone Claimed!',
        `+${formatNumber(milestone.reward)} bananas`,
        milestone.name,
        isQuestReward ? 'quest' : 'milestone',
        { duration: 1700, shake: isQuestReward ? false : 'normal' }
    );
    updateDisplay();
    updateProgressionPanel();
    saveGame();
}


function claimCollectionReward(rewardId) {
    ensureMonkeyRosterMatchesCount();
    const normalizedId = String(rewardId || '');
    const reward = COLLECTION_REWARDS.find((entry) => entry.id === normalizedId);

    if (!reward || claimedCollectionRewards.includes(normalizedId)) {
        return;
    }

    if (!canClaimCollectionReward(reward)) {
        updateProgressionPanel();
        return;
    }

    claimedCollectionRewards.push(normalizedId);

    if (reward.rewardBananas > 0) {
        addBananas(reward.rewardBananas);
    }

    const rewardText = getCollectionRewardText(reward).toUpperCase();
    spawnFloatingMessage(`COLLECTION: ${rewardText}`, 'is-collection');
    spawnHireBurst('is-collection');
    showCelebration('Collection Reward Claimed!', reward.name, getCollectionRewardText(reward), 'collection', { duration: 1900, shake: 'normal' });
    updateDisplay();
    updateProgressionPanel();
    saveGame();
    startMonkeyTypingEngine(true);
}

function claimOfficeCompletionReward(officeId) {
    const normalizedId = String(officeId || '');
    const office = OFFICE_BUILDINGS.find((entry) => entry.id === normalizedId);

    if (!office || claimedOfficeRewards.includes(normalizedId)) {
        return;
    }

    if (!isOfficeUnlocked(office) || !hasCompletedOfficeGoals(office)) {
        updateProgressionPanel();
        return;
    }

    claimedOfficeRewards.push(normalizedId);
    spawnFloatingMessage(`${office.name.toUpperCase()} COMPLETE`, 'is-super-rare');
    spawnFloatingMessage(getOfficeCompletionRewardText(office).toUpperCase(), 'is-hire');
    spawnHireBurst('is-office-complete');
    showCelebration('Office Complete!', office.name, getOfficeCompletionRewardText(office), 'office-complete', { duration: 2100, shake: 'normal' });
    updateDisplay();
    updateProgressionPanel();
    saveGame();
    startMonkeyTypingEngine(true);
}

function costButtonLabel(cost) {
    return `<span class="cost-inline"><span class="mini-banana-icon" aria-hidden="true"></span>${formatNumber(cost)}</span>`;
}

function getPanelTitle(view) {
    switch (view) {
        case 'milestones':
            return 'Milestones';
        case 'collection':
            return 'Monkey Collection';
        case 'quests':
            return 'Quests';
        default:
            return 'Office Upgrades';
    }
}

function setActivePanelView(view) {
    activePanelView = ['upgrades', 'milestones', 'collection', 'quests'].includes(view) ? view : 'upgrades';
}

function syncPanelVisibility() {
    const isUpgrades = activePanelView === 'upgrades';
    const isMilestones = activePanelView === 'milestones';
    const isCollection = activePanelView === 'collection';
    const isQuests = activePanelView === 'quests';

    panelBuildings.hidden = !isUpgrades;
    panelSkills.hidden = !isUpgrades;
    panelMilestones.hidden = !isMilestones;
    panelCollection.hidden = !isCollection;
    panelQuests.hidden = !isQuests;

    upgradePanelTitle.textContent = getPanelTitle(activePanelView);

    navPanelButtons.forEach((button) => {
        button.classList.toggle('is-active', button.dataset.panelView === activePanelView);
    });

    upgradeTabs.forEach((button) => {
        button.classList.toggle('is-active', button.dataset.panelTab === activePanelView);
    });
}

function renderMonkeyCollection() {
    if (!collectionList) {
        return;
    }

    const ownedTypeIds = getOwnedMonkeyTypeIds();
    const typeCounts = getMonkeyTypeCounts();
    const breakdown = getOwnedMonkeyTypeBreakdown(ownedTypeIds);
    const ownedCount = breakdown.totalOwned;
    const normalOwned = breakdown.normalOwned;
    const rareOwned = breakdown.rareOwned;
    const superRareOwned = breakdown.superRareOwned;
    const legendaryOwned = breakdown.legendaryOwned;
    const recentDiscoveries = discoveredWords.slice(-12).reverse();
    const collectionBonuses = getCollectionBonuses();
    const claimableRewards = getClaimableCollectionRewardCount();

    const renderBonusSection = () => {
        return `
            <section class="collection-section collection-bonus-section">
                <div class="collection-section-header">
                    <div>
                        <strong>Collection Bonuses</strong>
                        <span>Bonuses unlock automatically when you own enough unique monkey types.</span>
                    </div>
                </div>
                <div class="collection-bonus-grid">
                    ${COLLECTION_BONUS_DEFS.map((definition) => {
                        const progress = getCollectionBonusProgress(definition, breakdown);
                        const ratio = clamp(progress / definition.target, 0, 1);
                        const isActive = progress >= definition.target;

                        return `
                            <article class="collection-bonus-card ${isActive ? 'is-active' : ''}">
                                <div>
                                    <strong>${definition.reward}</strong>
                                    <span>${definition.label}</span>
                                </div>
                                <div class="milestone-bar" aria-hidden="true"><span style="width: ${Math.round(ratio * 100)}%"></span></div>
                                <small>${formatNumber(Math.min(progress, definition.target))} / ${formatNumber(definition.target)} ${getRarityLabelForGroup(definition.group)}</small>
                            </article>
                        `;
                    }).join('')}
                </div>
            </section>
        `;
    };

    const renderRewardSection = () => {
        return `
            <section class="collection-section collection-reward-section">
                <div class="collection-section-header">
                    <div>
                        <strong>Collection Rewards</strong>
                        <span>${claimableRewards} ready to claim • based on total monkeys hired.</span>
                    </div>
                </div>
                <div class="collection-reward-list">
                    ${COLLECTION_REWARDS.map((reward) => {
                        const progress = getCollectionRewardProgress(reward);
                        const ratio = clamp(progress / reward.target, 0, 1);
                        const isClaimed = claimedCollectionRewards.includes(reward.id);
                        const isReady = canClaimCollectionReward(reward);

                        return `
                            <article class="collection-reward-card ${isClaimed ? 'is-claimed' : ''} ${isReady ? 'is-ready' : ''}">
                                <div class="collection-reward-copy">
                                    <strong>${reward.name}</strong>
                                    <span>${reward.description}</span>
                                    <div class="milestone-bar" aria-hidden="true"><span style="width: ${Math.round(ratio * 100)}%"></span></div>
                                    <small>${formatNumber(progress)} / ${formatNumber(reward.target)} • ${getCollectionRewardText(reward)}</small>
                                </div>
                                <button type="button" class="progress-buy-button collection-claim-button" data-collection-reward-id="${reward.id}" ${!isReady ? 'disabled' : ''}>${isClaimed ? 'Claimed' : isReady ? 'Claim' : 'Locked'}</button>
                            </article>
                        `;
                    }).join('')}
                </div>
            </section>
        `;
    };

    const renderSection = (title, subtitle, rarity) => {
        const sectionTypes = MONKEY_TYPES.filter((type) => type.rarity === rarity);

        return `
            <section class="collection-section">
                <div class="collection-section-header">
                    <div>
                        <strong>${title}</strong>
                        <span>${subtitle}</span>
                    </div>
                </div>
                <div class="collection-grid">
                    ${sectionTypes.map((monkeyType) => {
                        const isOwned = ownedTypeIds.has(monkeyType.id);
                        const ownedCopies = typeCounts[monkeyType.id] || 0;
                        const rarityClass = getRarityClass(monkeyType.rarity);

                        return `
                            <article class="collection-card ${isOwned ? 'is-owned' : 'is-locked'} ${rarityClass}">
                                <div class="collection-art">
                                    ${isOwned ? `<img src="${getMonkeySpriteSrc(monkeyType)}" alt="" />` : '<span class="locked-silhouette">?</span>'}
                                </div>
                                <div class="collection-card-meta">
                                    <strong>${isOwned ? monkeyType.name : 'Locked Monkey'}</strong>
                                    <span class="collection-rarity">${getMonkeyRarityLabel(monkeyType)} • ${monkeyType.speedMultiplier}x speed</span>
                                </div>
                                <div class="collection-card-footer">
                                    <span class="collection-owned-badge">${isOwned ? `${ownedCopies} owned` : 'Not found'}</span>
                                </div>
                            </article>
                        `;
                    }).join('')}
                </div>
            </section>
        `;
    };

    const renderWordDiscoverySection = () => {
        return `
            <section class="collection-section word-discovery-section">
                <div class="collection-section-header">
                    <div>
                        <strong>Word Discoveries</strong>
                        <span>Unique words found, best payout, and longest word.</span>
                    </div>
                </div>
                <div class="word-discovery-summary">
                    <div><strong>${formatNumber(getDiscoveredWordCount())}</strong><span>Unique</span></div>
                    <div><strong>${lifetimeStats.bestWord ? getDisplayWord(lifetimeStats.bestWord, 8).toUpperCase() : '—'}</strong><span>Best: ${formatNumber(lifetimeStats.bestWordPoints)}</span></div>
                    <div><strong>${lifetimeStats.longestWord ? getDisplayWord(lifetimeStats.longestWord, 8).toUpperCase() : '—'}</strong><span>Longest</span></div>
                </div>
                <div class="word-discovery-list">
                    ${recentDiscoveries.length > 0
                        ? recentDiscoveries.map((word) => `<span>${getDisplayWord(word, 9).toUpperCase()}</span>`).join('')
                        : '<em>Find words to fill the dictionary.</em>'}
                </div>
            </section>
        `;
    };

    collectionList.innerHTML = `
        <div class="collection-summary">
            <div>
                <strong>${ownedCount} / ${MONKEY_TYPES.length} monkeys collected</strong>
                <span>${normalOwned} normal • ${rareOwned} rare • ${superRareOwned} super rare • ${legendaryOwned} legendary • ${claimableRewards} rewards ready</span>
            </div>
            <div class="collection-summary-side">
                <strong>${Math.round(getSuperRareChance() * 100)}%</strong>
                <span>Super rare odds</span>
            </div>
        </div>
        <div class="collection-active-bonuses">
            <span>Speed +${Math.round(collectionBonuses.speedBonus * 100)}%</span>
            <span>Income +${Math.round(collectionBonuses.incomeBonus * 100)}%</span>
            <span>Super rare odds +${Math.round(collectionBonuses.rareBonus * 100)}%</span>
        </div>
        ${renderRewardSection()}
        ${renderBonusSection()}
        ${renderWordDiscoverySection()}
        ${renderSection('Normal Monkeys', 'Your everyday typing crew.', 'normal')}
        ${renderSection('Rare Monkeys', 'Faster hires with special styles.', 'rare')}
        ${renderSection('Super Rare Monkeys', 'High-value hires with boosted speed.', 'super-rare')}
        ${renderSection('Legendary Monkeys', 'Ultra-rare monkeys that transcend the office.', 'legendary')}
    `;
}

function renderQuests() {
    if (!questsList) {
        return;
    }

    const unlockedTier = getUnlockedQuestTier();
    const lockedQuestCount = getLockedQuestCount();
    const activeQuests = getUnclaimedMilestones('quest').sort(sortProgressGoals).slice(0, 6);
    if (questsBadge) questsBadge.textContent = String(getClaimableQuestCount());

    const tierHeader = `
        <div class="quest-tier-header">
            <div>
                <strong>Quest Tier ${unlockedTier}</strong>
                <span>${activeQuests.length} active goals${lockedQuestCount > 0 ? ` • ${lockedQuestCount} locked for later` : ''}</span>
            </div>
            <em>${getClaimableQuestCount()} ready</em>
        </div>
    `;

    if (activeQuests.length === 0) {
        questsList.innerHTML = `
            ${tierHeader}
            <article class="quest-card compact-quest-card is-complete">
                <div class="quest-art"><img src="icon-quests.png" alt="" /></div>
                <div class="quest-main">
                    <h3>All visible quests complete</h3>
                    <p>Unlock the next office tier to reveal more goals.</p>
                </div>
            </article>
        `;
        return;
    }

    questsList.innerHTML = `
        ${tierHeader}
        ${activeQuests.map((milestone) => {
            const progress = getMilestoneProgress(milestone);
            const ratio = clamp(progress / milestone.target, 0, 1);
            const isReady = progress >= milestone.target;
            const percent = Math.round(ratio * 100);

            return `
                <article class="quest-card compact-quest-card ${isReady ? 'is-ready' : ''}">
                    <div class="quest-art"><img src="${getQuestIconSrc(milestone)}" alt="" /></div>
                    <div class="quest-main">
                        <h3>${milestone.name}</h3>
                        <p>${milestone.description}</p>
                        <div class="milestone-bar" aria-hidden="true"><span style="width: ${percent}%"></span></div>
                        <small>${formatNumber(Math.min(progress, milestone.target))} / ${formatNumber(milestone.target)}</small>
                    </div>
                    <div class="quest-side">
                        <div class="quest-reward-label"><b>Reward</b><span><img src="icon-bananas.png" alt="" /> ${formatNumber(milestone.reward)}</span></div>
                        <button class="progress-buy-button milestone-claim-button" data-milestone-id="${milestone.id}" ${!isReady ? 'disabled' : ''}>${isReady ? 'Claim' : 'Active'}</button>
                    </div>
                </article>
            `;
        }).join('')}
    `;
}


function getUpgradeEffectValue(upgradeId, level) {
    switch (upgradeId) {
        case 'fasterTypewriters':
            return `+${Math.round(level * 8)}% speed`;
        case 'betterDictionary':
            return `+${level} banana${level === 1 ? '' : 's'} per word`;
        case 'bananaPayroll':
            return `+${Math.round(level * 12)}% word income`;
        case 'rareRecruiter':
            return `+${level}% super rare odds`;
        default:
            return `Level ${level}`;
    }
}

function renderUpgradeCard(upgradeId) {
    const upgrade = UPGRADE_DEFS[upgradeId];
    const level = getUpgradeLevel(upgradeId);
    const isMaxed = level >= upgrade.maxLevel;
    const cost = isMaxed ? 0 : getUpgradeCost(upgradeId);
    const canAfford = !isMaxed && bananas >= cost;
    const currentEffect = getUpgradeEffectValue(upgradeId, level);
    const nextEffect = isMaxed ? 'Maxed' : getUpgradeEffectValue(upgradeId, level + 1);

    return `
        <article class="progress-card upgrade-card-rich ${canAfford ? 'is-affordable' : ''}">
            <div class="progress-card-copy">
                <span class="progress-branch">${upgrade.branch}</span>
                <h3>${upgrade.name}</h3>
                <p>${upgrade.description}</p>
                <div class="upgrade-effect-row"><span>Current</span><strong>${currentEffect}</strong></div>
                <div class="upgrade-effect-row is-next"><span>Next</span><strong>${nextEffect}</strong></div>
                <span class="progress-meta">Level ${level} / ${upgrade.maxLevel}</span>
            </div>
            <button class="progress-buy-button" data-upgrade-id="${upgrade.id}" ${(!canAfford || isMaxed) ? 'disabled' : ''}>
                ${isMaxed ? 'Maxed' : costButtonLabel(cost)}
            </button>
        </article>
    `;
}


function getOfficeBonusSummary(office) {
    const parts = [];

    if (office.speedBonus > 0) {
        parts.push(`+${Math.round(office.speedBonus * 100)}% speed`);
    }

    if (office.wordBonus > 0) {
        parts.push(`+${office.wordBonus} word bonus`);
    }

    if (office.incomeMultiplier > 1) {
        parts.push(`${office.incomeMultiplier.toFixed(2)}x income`);
    }

    if (office.rareBonus > 0) {
        parts.push(`+${Math.round(office.rareBonus * 100)}% super rare odds`);
    }

    return parts.length > 0 ? parts.join(' • ') : 'No bonus yet';
}

function updateProgressionPanel() {
    if (!officeUpgradeList || !skillsUpgradeList || !milestonesList) {
        return;
    }

    const currentOffice = getCurrentOffice();
    const nextOffice = getNextOffice();

    currentOfficeNameEl.textContent = `${currentOffice.name} — Floor ${currentOffice.floor}`;
    currentOfficeBonusEl.textContent = currentOffice.description || 'A small office with big potential.';

    if (currentOfficeThumbEl && !currentOfficeThumbEl.querySelector('img')) {
        currentOfficeThumbEl.innerHTML = '<img src="office-bg.png" alt="">';
    }


    if (currentOfficePerksEl) {
        currentOfficePerksEl.innerHTML = [...getOfficePerkBadges(currentOffice), ...getOfficeCompletionPerkBadges()]
            .map((perk) => `<span class="perk-chip"><img src="${perk.icon}" alt="" />${perk.text}</span>`)
            .join('');
    }

    const canUnlockNextOffice = Boolean(nextOffice && bananas >= nextOffice.unlockCost && meetsOfficeRequirements(nextOffice));
    const officeCompletionBonusText = getCollectionRewardBonusText(getClaimedOfficeRewardBonuses()) || 'Complete offices to earn permanent chapter bonuses.';
    const officeCards = OFFICE_BUILDINGS.map((office) => renderOfficeCompletionCard(office, { showDescription: office.id === currentOffice.id })).join('');

    officeUpgradeList.innerHTML = `
        <div class="office-system-summary">
            <div>
                <strong>${formatNumber(getClaimableOfficeRewardCount())}</strong>
                <span>office bonus${getClaimableOfficeRewardCount() === 1 ? '' : 'es'} ready</span>
            </div>
            <div>
                <strong>${claimedOfficeRewards.length}/${OFFICE_BUILDINGS.length}</strong>
                <span>chapters complete</span>
            </div>
            <div>
                <strong>${Math.round(getOfficeCompletionPercent(currentOffice))}%</strong>
                <span>current office</span>
            </div>
        </div>
        <article class="progress-card office-progress-card office-progress-rich ${canUnlockNextOffice ? 'is-affordable' : ''}">
            <div class="progress-card-copy">
                <span class="progress-branch">Next Office</span>
                <h3>${nextOffice ? `${nextOffice.name} — Floor ${nextOffice.floor}` : 'All Offices Unlocked'}</h3>
                <p>${nextOffice ? nextOffice.description : 'You have reached the top of the monkey business ladder.'}</p>
                <div class="upgrade-perks-inline">
                    ${getOfficePerkBadges(nextOffice || currentOffice).map((perk) => `<span class="perk-chip"><img src="${perk.icon}" alt="" />${perk.text}</span>`).join('')}
                </div>
                ${nextOffice ? renderOfficeRequirements(nextOffice) : '<div class="office-requirements"><span class="office-requirement is-complete">Every floor unlocked</span></div>'}
                <span class="progress-meta">${nextOffice ? `Unlock cost ${formatNumber(nextOffice.unlockCost)} bananas` : 'Every office has been unlocked'} • Permanent bonuses: ${officeCompletionBonusText}</span>
            </div>
            <button class="progress-buy-button" data-office-unlock="true" ${(!nextOffice || !canUnlockNextOffice) ? 'disabled' : ''}>
                ${nextOffice ? costButtonLabel(nextOffice.unlockCost) : 'Maxed'}
            </button>
        </article>
        <div class="office-chapter-heading">
            <strong>Office Chapters</strong>
            <span>Finish goals inside each unlocked office to earn permanent bonuses.</span>
        </div>
        ${officeCards}
    `;

    skillsUpgradeList.innerHTML = Object.keys(UPGRADE_DEFS).map(renderUpgradeCard).join('');

    const longTermMilestones = MILESTONES
        .filter(isLongTermMilestone)
        .sort(sortProgressGoals);

    milestonesList.innerHTML = longTermMilestones.map((milestone) => {
        const progress = getMilestoneProgress(milestone);
        const ratio = clamp(progress / milestone.target, 0, 1);
        const isClaimed = claimedMilestones.includes(milestone.id);
        const isReady = progress >= milestone.target && !isClaimed;

        return `
            <article class="milestone-card ${isClaimed ? 'is-claimed' : ''} ${isReady ? 'is-ready' : ''}">
                <div class="milestone-copy">
                    <h3>${milestone.name}</h3>
                    <p>${milestone.description}</p>
                    <div class="milestone-bar" aria-hidden="true">
                        <span style="width: ${Math.round(ratio * 100)}%"></span>
                    </div>
                    <small>${formatNumber(Math.min(progress, milestone.target))} / ${formatNumber(milestone.target)} • Reward ${formatNumber(milestone.reward)} bananas</small>
                </div>
                <button class="progress-buy-button milestone-claim-button" data-milestone-id="${milestone.id}" ${!isReady ? 'disabled' : ''}>
                    ${isClaimed ? 'Claimed' : isReady ? 'Claim' : 'Active'}
                </button>
            </article>
        `;
    }).join('');

    renderMonkeyCollection();
    renderQuests();
    syncPanelVisibility();
    bindProgressionButtons();
}
function canAffordOfficeUnlock() {
    const nextOffice = getNextOffice();
    return Boolean(nextOffice && bananas >= nextOffice.unlockCost);
}

function runProgressionButtonAction(button) {
    if (!button || button.disabled) {
        return;
    }

    if (button.matches('[data-office-unlock]')) {
        unlockNextOffice();
        return;
    }

    if (button.dataset.upgradeId) {
        buyUpgrade(button.dataset.upgradeId);
        return;
    }

    if (button.dataset.milestoneId) {
        claimMilestone(button.dataset.milestoneId);
        return;
    }

    if (button.dataset.collectionRewardId) {
        claimCollectionReward(button.dataset.collectionRewardId);
        return;
    }

    if (button.dataset.officeRewardId) {
        claimOfficeCompletionReward(button.dataset.officeRewardId);
    }
}

function bindProgressionActionArea(container) {
    if (!container || container.dataset.delegatedBound) {
        return;
    }

    container.dataset.delegatedBound = 'true';
    let handledByPointer = false;
    let lastHandledAt = 0;

    const findActionButton = (target) => {
        return target && target.closest
            ? target.closest('[data-office-unlock], [data-upgrade-id], [data-milestone-id], [data-collection-reward-id], [data-office-reward-id]')
            : null;
    };

    const handleActionEvent = (event, fromPointer = false) => {
        if (event.mbProgressionHandled) {
            return true;
        }

        const button = findActionButton(event.target);
        if (!button || !container.contains(button) || button.disabled) {
            return false;
        }

        if (fromPointer && event.pointerType === 'mouse' && event.button !== 0) {
            return false;
        }

        const now = Date.now();
        if (now - lastHandledAt < 260) {
            event.preventDefault();
            event.stopPropagation();
            return true;
        }

        lastHandledAt = now;
        event.mbProgressionHandled = true;
        event.preventDefault();
        event.stopPropagation();
        runProgressionButtonAction(button);
        return true;
    };

    container.addEventListener('pointerdown', (event) => {
        handledByPointer = handleActionEvent(event, true);
    });

    container.addEventListener('touchend', (event) => {
        if (!handledByPointer) {
            handledByPointer = handleActionEvent(event, false);
        }
    }, { passive: false });

    container.addEventListener('click', (event) => {
        if (handledByPointer) {
            handledByPointer = false;
            event.preventDefault();
            event.stopPropagation();
            return;
        }

        handleActionEvent(event, false);
    });
}

function bindProgressionButtons() {
    // Dynamic progress cards are rebuilt often. Delegated handlers below are bound once,
    // so claim/buy buttons remain reliable after every render.
}

function openUpgradesPanel(view = 'upgrades') {
    setActivePanelView(view);
    updateProgressionPanel();
    upgradePanel.classList.remove('is-hidden');
    upgradePanel.setAttribute('aria-hidden', 'false');
}

function closeUpgradesPanel() {
    upgradePanel.classList.add('is-hidden');
    upgradePanel.setAttribute('aria-hidden', 'true');
}

function saveGame() {
    lastActiveAt = Date.now();

    const saveData = {
        bananas,
        lettersTyped,
        wordsTyped,
        monkeysOwned,
        monkeyCost,
        typedStream,
        recentWords,
        monkeyRoster,
        officeLevel,
        upgrades,
        claimedMilestones,
        claimedCollectionRewards,
        claimedOfficeRewards,
        lifetimeStats,
        discoveredWords,
        lastActiveAt
    };

    localStorage.setItem(SAVE_KEY, JSON.stringify(saveData));
    LEGACY_SAVE_KEYS.forEach((key) => {
        if (key !== SAVE_KEY) {
            localStorage.removeItem(key);
        }
    });
}

function loadGame() {
    const availableKeys = [SAVE_KEY, ...LEGACY_SAVE_KEYS];
    let rawSave = null;
    let loadedSaveKey = null;

    for (const key of availableKeys) {
        rawSave = localStorage.getItem(key);
        if (rawSave) {
            loadedSaveKey = key;
            break;
        }
    }

    if (!rawSave) {
        ensureProgressionState();
        return;
    }

    try {
        const saveData = JSON.parse(rawSave);

        bananas = Number(saveData.bananas) || 0;
        lettersTyped = Number(saveData.lettersTyped) || 0;
        wordsTyped = Number(saveData.wordsTyped) || 0;
        monkeysOwned = Number(saveData.monkeysOwned) || 0;
        monkeyCost = Number(saveData.monkeyCost) || HIRE_COST_START;
        if (loadedSaveKey !== SAVE_KEY) {
            monkeyCost = Math.max(1, Math.ceil(monkeyCost * HIRE_COST_REDUCTION_MULTIPLIER));
        }
        typedStream = typeof saveData.typedStream === 'string' ? saveData.typedStream.slice(-maxSavedStreamLength) : '';
        recentWords = Array.isArray(saveData.recentWords) ? saveData.recentWords.slice(0, recentWordLimit) : [];
        normalizeRecentWords();
        monkeyRoster = Array.isArray(saveData.monkeyRoster) ? saveData.monkeyRoster.map(normalizeRosterEntry) : [];
        officeLevel = Number(saveData.officeLevel) || 1;
        upgrades = { ...upgrades, ...(saveData.upgrades || {}) };
        claimedMilestones = Array.isArray(saveData.claimedMilestones) ? saveData.claimedMilestones : [];
        claimedCollectionRewards = Array.isArray(saveData.claimedCollectionRewards) ? saveData.claimedCollectionRewards : [];
        claimedOfficeRewards = Array.isArray(saveData.claimedOfficeRewards) ? saveData.claimedOfficeRewards : [];
        discoveredWords = normalizeDiscoveredWords(saveData.discoveredWords || recentWords.map((entry) => entry.word));
        lifetimeStats = normalizeLifetimeStats(saveData.lifetimeStats || {});
        lastActiveAt = Number(saveData.lastActiveAt) || Date.now();

        ensureProgressionState();
        ensureMonkeyRosterMatchesCount();
    } catch (error) {
        console.warn('Could not load saved Monkey Business game.', error);
        availableKeys.forEach((key) => localStorage.removeItem(key));
        ensureProgressionState();
    }
}

function resetGame() {
    const shouldReset = window.confirm('Reset Monkey Business and clear your saved bananas, words, monkeys, offices, upgrades, and goals?');

    if (!shouldReset) {
        return;
    }

    bananas = 0;
    lettersTyped = 0;
    wordsTyped = 0;
    monkeysOwned = 0;
    monkeyCost = HIRE_COST_START;
    typedStream = '';
    recentWords = [];
    monkeyRoster = [];
    officeLevel = 1;
    upgrades = {
        fasterTypewriters: 0,
        betterDictionary: 0,
        bananaPayroll: 0,
        rareRecruiter: 0
    };
    claimedMilestones = [];
    claimedCollectionRewards = [];
    claimedOfficeRewards = [];
    discoveredWords = [];
    lifetimeStats = getDefaultLifetimeStats();
    lastActiveAt = Date.now();

    monkeyAnimationTimeouts.forEach((timeoutId) => clearTimeout(timeoutId));
    monkeyAnimationTimeouts.clear();
    stopMonkeyTypingEngine();

    [SAVE_KEY, ...LEGACY_SAVE_KEYS].forEach((key) => localStorage.removeItem(key));
    outputArea.innerHTML = '<span class="placeholder">Tap TYPE to begin...</span>';
    if (floatingRewardsLayer) {
        floatingRewardsLayer.innerHTML = '';
    }
    if (celebrationOverlay) {
        celebrationOverlay.replaceChildren();
        celebrationOverlay.classList.remove('is-visible');
        celebrationOverlay.setAttribute('aria-hidden', 'true');
    }
    updateDisplay();
    startMonkeyTypingEngine(false);
}

function bindFastTap(button, handler) {
    let handledByPointer = false;

    button.addEventListener('pointerdown', (event) => {
        if (event.pointerType === 'mouse' && event.button !== 0) {
            return;
        }

        handledByPointer = true;
        event.preventDefault();
        handler();
    });

    button.addEventListener('click', (event) => {
        if (handledByPointer) {
            handledByPointer = false;
            event.preventDefault();
            return;
        }

        handler();
    });
}

bindProgressionActionArea(officeUpgradeList);
bindProgressionActionArea(skillsUpgradeList);
bindProgressionActionArea(milestonesList);
bindProgressionActionArea(questsList);
bindProgressionActionArea(collectionList);
bindProgressionActionArea(upgradePanel);

