resetButton.addEventListener('click', resetGame);
navPanelButtons.forEach((button) => {
    button.addEventListener('click', () => openUpgradesPanel(button.dataset.panelView));
});

upgradeTabs.forEach((button) => {
    button.addEventListener('click', () => {
        setActivePanelView(button.dataset.panelTab);
        updateProgressionPanel();
    });
});
closeUpgradesButton.addEventListener('click', closeUpgradesPanel);
upgradePanel.addEventListener('click', (event) => {
    if (event.target === upgradePanel) {
        closeUpgradesPanel();
    }
});


document.addEventListener('visibilitychange', () => {
    if (document.hidden) {
        saveGame();
        stopMonkeyTypingEngine();
        return;
    }

    processOfflineEarnings({ showSummary: true });
    forceMonkeyOfficeRender();
    startMonkeyTypingEngine(true);
});

window.addEventListener('pagehide', () => {
    saveGame();
});

window.addEventListener('beforeunload', () => {
    saveGame();
});

document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape' && !upgradePanel.classList.contains('is-hidden')) {
        closeUpgradesPanel();
    }
});

window.MonkeyBusinessDebug = {
    getState() {
        return {
            bananas,
            lettersTyped,
            wordsTyped,
            monkeysOwned,
            monkeyCost,
            monkeyRoster: [...monkeyRoster],
            monkeyNextTypeAt: [...monkeyNextTypeAt],
            officeLevel,
            upgrades: { ...upgrades },
            claimedMilestones: [...claimedMilestones],
            claimedCollectionRewards: [...claimedCollectionRewards],
            claimedOfficeRewards: [...claimedOfficeRewards],
            officeCompletionBonuses: getClaimedOfficeRewardBonuses(),
            collectionBonuses: getCollectionBonuses(),
            recentWords: [...recentWords],
            lifetimeStats: { ...lifetimeStats },
            discoveredWords: [...discoveredWords],
            unlockedQuestTier: getUnlockedQuestTier(),
            lastActiveAt,
            offlineCapMs: getOfflineEarningsCapMs()
        };
    },
    setState(partialState = {}) {
        if (Number.isFinite(Number(partialState.bananas))) bananas = Number(partialState.bananas);
        if (Number.isFinite(Number(partialState.lettersTyped))) lettersTyped = Number(partialState.lettersTyped);
        if (Number.isFinite(Number(partialState.wordsTyped))) wordsTyped = Number(partialState.wordsTyped);
        if (Number.isFinite(Number(partialState.monkeysOwned))) monkeysOwned = Math.max(0, Number(partialState.monkeysOwned));
        if (Number.isFinite(Number(partialState.monkeyCost))) monkeyCost = Math.max(1, Number(partialState.monkeyCost));
        if (typeof partialState.typedStream === 'string') typedStream = partialState.typedStream.slice(-maxSavedStreamLength);
        if (Array.isArray(partialState.monkeyRoster)) monkeyRoster = partialState.monkeyRoster.map(normalizeRosterEntry);
        if (Number.isFinite(Number(partialState.officeLevel))) officeLevel = clamp(Number(partialState.officeLevel), 1, OFFICE_BUILDINGS.length);
        if (partialState.upgrades && typeof partialState.upgrades === 'object') upgrades = { ...upgrades, ...partialState.upgrades };
        if (Array.isArray(partialState.claimedMilestones)) claimedMilestones = partialState.claimedMilestones.map(String);
        if (Array.isArray(partialState.claimedCollectionRewards)) claimedCollectionRewards = partialState.claimedCollectionRewards.map(String);
        if (Array.isArray(partialState.claimedOfficeRewards)) claimedOfficeRewards = partialState.claimedOfficeRewards.map(String);
        if (Array.isArray(partialState.discoveredWords)) discoveredWords = normalizeDiscoveredWords(partialState.discoveredWords);
        if (partialState.lifetimeStats && typeof partialState.lifetimeStats === 'object') lifetimeStats = normalizeLifetimeStats(partialState.lifetimeStats);
        if (Number.isFinite(Number(partialState.lastActiveAt))) lastActiveAt = Number(partialState.lastActiveAt);
        ensureMonkeyRosterMatchesCount();
        ensureProgressionState();
        forceMonkeyOfficeRender();
        updateDisplay();
        saveGame();
        startMonkeyTypingEngine(true);
    },
    claimMilestone,
    claimCollectionReward,
    claimOfficeCompletionReward,
    getCollectionBonuses,
    getClaimedOfficeRewardBonuses,
    runMonkeyTyping,
    buyMonkey,
    typeRandomLetter,
    awardWords,
    calculateWordPoints,
    updateDisplay,
    calculateOfflineEarnings,
    processOfflineEarnings,
    showCelebration,
    startMonkeyTypingEngine
};

